'use client';

import { useEffect, useState } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { Product, getProductTypeLabel } from '@/types/product';
import { useMarketplaceBuy } from '@/components/marketplace/hooks/useMarketplaceBuy';
import { BuyOrderModal } from '@/components/marketplace/modals/BuyOrderModal';
import { ConfirmBuyModal } from '@/components/marketplace/modals/ConfirmBuyModal';
import { ProductCarousel } from '@/components/multimedia/ProductCarousel';
import { Star, ShoppingBag, Settings2, ShieldCheck, Truck, RefreshCcw, Leaf, MessageSquareText } from 'lucide-react';

interface Props {
  initialProduct: Product;
}

export const ProductDetailView = ({ initialProduct }: Props) => {
  const router = useRouter();
  const { attrValues, errors, loading, quantity, setQuantity, initAttributes, setField, createOrder, resetForm, validateForm } = useMarketplaceBuy();

  const [showBuyModal, setShowBuyModal] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  // Optional: Add state for image gallery if we had multiple images.
  const [mainImage, setMainImage] = useState(initialProduct.imageUrl);

  const handleBuyClick = () => {
    const token = localStorage.getItem('token');
    if (!token) {
      localStorage.setItem('redirect_after_login', `/marketplace/${initialProduct.id}`);
      router.push('/login');
      return;
    }
    resetForm();
    setQuantity(1);
    setShowBuyModal(true);
  };

  const handleBuyConfirm = () => {
    const isValid = validateForm(initialProduct.attributes, initialProduct.stock);
    if (!isValid) return;
    setShowBuyModal(false);
    setShowConfirmModal(true);
  };

  const handleFinalConfirm = async () => {
    const success = await createOrder(initialProduct.id, initialProduct.title, initialProduct.attributes, initialProduct.stock);
    if (success) {
      setShowConfirmModal(false);
      resetForm();
      // Possibly redirect or show success toast
    }
  };

  // Mocking extra images for the gallery
  const thumbnails = [
    initialProduct.imageUrl,
    // Add same image to demonstrate layout since we only have 1 image per product
    initialProduct.imageUrl,
    initialProduct.imageUrl,
  ];

  return (
    <div className="pt-6 lg:pt-10 pb-16 lg:pb-24 min-h-screen">
      <div className="max-w-[1440px] mx-auto px-4 sm:px-6 lg:px-8">
        {/* Breadcrumbs */}
        <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground mb-6 lg:mb-8 bg-muted/30 w-fit px-4 py-2 rounded-full border border-border/50">
          <Link href="/marketplace" className="hover:text-primary transition-colors font-medium">Marketplace</Link>
          <span className="text-border">/</span>
          <Link href={`/marketplace?type=${initialProduct.productType}`} className="capitalize hover:text-primary transition-colors font-medium">
            {getProductTypeLabel(initialProduct.productType)}
          </Link>
          <span className="text-border">/</span>
          <span className="text-foreground font-semibold line-clamp-1">{initialProduct.title}</span>
        </div>

        {/* Product Grid Layout */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-16">

          {/* Left: Image Gallery */}
          <div className="lg:col-span-7 w-full">
            <ProductCarousel media={initialProduct.media || []} altText={initialProduct.title} />
          </div>

          {/* Right: Product Information */}
          <div className="lg:col-span-5 flex flex-col pt-0 lg:pt-4">

            {/* Title & Price Block */}
            <div className="mb-6 lg:mb-8">
              <h1 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold text-foreground leading-[1.1] tracking-tight mb-6 text-balance">
                {initialProduct.title}
              </h1>

              <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
                <div className="flex items-baseline gap-2">
                  <span className="text-4xl lg:text-5xl font-black text-primary tracking-tight">
                    ${initialProduct.price.toLocaleString()}
                  </span>
                  <span className="text-sm text-muted-foreground font-medium uppercase tracking-wider">COP</span>
                </div>

                {initialProduct.reviews > 0 && (
                  <button
                    type="button"
                    onClick={() => document.getElementById('opiniones')?.scrollIntoView({ behavior: 'smooth' })}
                    className="flex items-center gap-2 bg-yellow-500/10 px-3 py-1.5 rounded-full border border-yellow-500/20 hover:bg-yellow-500/20 hover:scale-105 active:scale-95 transition-all"
                  >
                    <Star className="w-4 h-4 fill-yellow-500 text-yellow-500" />
                    <span className="font-bold text-yellow-600 dark:text-yellow-400 text-sm flex items-center gap-1.5">
                      {Number(initialProduct.rating).toFixed(1)}
                      <span className="font-normal text-yellow-600/70 dark:text-yellow-400/70">({initialProduct.reviews})</span>
                    </span>
                  </button>
                )}
              </div>

              <div className="inline-flex items-center gap-2 text-xs lg:text-sm font-semibold px-3 py-1.5 rounded-full bg-background border shadow-sm">
                {initialProduct.inStock ? (
                  <>
                    <span className="relative flex h-2.5 w-2.5">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-green-500"></span>
                    </span>
                    <span className="text-green-600 dark:text-green-400">En stock - Listo para enviar</span>
                  </>
                ) : (
                  <>
                    <span className="w-2.5 h-2.5 rounded-full bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.6)]"></span>
                    <span className="text-red-600 dark:text-red-400">Agotado temporalmente</span>
                  </>
                )}
              </div>
            </div>

            {/* Description */}
            <div className="prose prose-sm sm:prose-base dark:prose-invert text-muted-foreground leading-relaxed mb-8 lg:mb-10 max-w-lg">
              <p>{initialProduct.description}</p>
            </div>

            {/* Action Area */}
            <div className="flex flex-col gap-3 lg:gap-4 mt-auto p-5 lg:p-6 bg-muted/20 rounded-2xl border border-border/50">
              <button
                onClick={handleBuyClick}
                disabled={!initialProduct.inStock}
                className="w-full bg-gradient-to-r from-primary to-accent text-white py-4 rounded-xl font-bold text-base lg:text-lg tracking-wide uppercase shadow-lg shadow-primary/25 hover:shadow-primary/40 transition-all duration-300 hover:-translate-y-0.5 active:translate-y-0 flex items-center justify-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:translate-y-0 disabled:hover:shadow-none"
              >
                <span>Comprar Ahora</span>
                <ShoppingBag className="w-5 h-5" />
              </button>

              <Link
                href="/cliente/crear-pedido"
                className="w-full bg-background text-foreground py-3.5 rounded-xl font-semibold text-xs lg:text-sm tracking-wide uppercase hover:bg-muted transition-colors duration-300 flex items-center justify-center gap-2 border border-border hover:border-foreground/20 shadow-sm"
              >
                <Settings2 className="w-4 h-4 lg:w-5 lg:h-5 text-muted-foreground" />
                Crear un pedido personalizado
              </Link>
            </div>

            {/* Perks List */}
            <div className="mt-6 lg:mt-8 grid grid-cols-2 gap-4">
              <div className="flex items-center gap-3 group p-3 rounded-xl hover:bg-muted/50 transition-colors border border-transparent hover:border-border/50">
                <div className="p-2.5 bg-primary/10 rounded-lg text-primary group-hover:scale-110 transition-transform">
                  <Leaf className="w-5 h-5" />
                </div>
                <span className="text-sm font-semibold text-foreground/80">Material premium</span>
              </div>
              <div className="flex items-center gap-3 group p-3 rounded-xl hover:bg-muted/50 transition-colors border border-transparent hover:border-border/50">
                <div className="p-2.5 bg-primary/10 rounded-lg text-primary group-hover:scale-110 transition-transform">
                  <RefreshCcw className="w-5 h-5" />
                </div>
                <span className="text-sm font-semibold text-foreground/80">Soporte 24/7</span>
              </div>
            </div>

          </div>
        </div>
      </div>

      {/* Buy Modals */}
      <BuyOrderModal
        product={initialProduct}
        isOpen={showBuyModal}
        onClose={() => setShowBuyModal(false)}
        attrValues={attrValues}
        errors={errors}
        loading={loading}
        quantity={quantity}
        onQuantityChange={setQuantity}
        onFieldChange={setField}
        onConfirm={handleBuyConfirm}
        initAttributes={initAttributes}
      />
      <ConfirmBuyModal
        productTitle={initialProduct.title}
        quantity={quantity}
        totalAmount={(Number(initialProduct.price || 0) * quantity) + Math.round(Number(initialProduct.price || 0) * quantity * 0.19 * 100) / 100}
        isOpen={showConfirmModal}
        onConfirm={handleFinalConfirm}
        onCancel={() => {
          setShowConfirmModal(false);
          setShowBuyModal(true);
        }}
        loading={loading}
      />
    </div>
  );
};

import { ProductService } from "@/services/product.service";
import { ProductDetailView } from "./ProductDetailView";
import Header from "@/components/Header";

interface PageProps {
  params: Promise<{
    id: string;
  }>;
}

// Opcional: generar metadatos para SEO
export async function generateMetadata({ params }: PageProps) {
  try {
    const resolvedParams = await params;
    const product = await ProductService.getProductById(resolvedParams.id);
    return {
      title: `${product.title} - DesignForge`,
      description: product.description,
    };
  } catch (error) {
    return {
      title: "Producto no encontrado - DesignForge",
    };
  }
}

export default async function ProductDetailPage({ params }: PageProps) {
  try {
    const resolvedParams = await params;
    const product = await ProductService.getProductById(resolvedParams.id);

    return (
      <div className="bg-background text-foreground flex flex-col">
        <Header />
        <main className="flex-1">
          <ProductDetailView initialProduct={product} />
        </main>
      </div>
    );
  } catch (error) {
    return (
      <div className="flex flex-col">
        <Header />
        <main className="flex-1 flex flex-col items-center justify-center p-8 text-center min-h-[60vh]">
          <h1 className="text-3xl font-bold mb-4">Producto no encontrado</h1>
          <p className="text-muted-foreground mb-8">
            El producto que buscas no existe o ha sido removido.
          </p>
          <a
            href="/marketplace"
            className="bg-primary text-primary-foreground px-6 py-2 rounded-lg font-medium hover:bg-primary/90 transition-colors"
          >
            Volver al Marketplace
          </a>
        </main>
      </div>
    );
  }
}

'use client';

import { useState } from 'react';

import Header from '@/components/Header';
import { Card, CardContent } from '@/components/ui/card';

import { useAdminMarketplace } from '@/components/marketplace/hooks/useAdminMarketplace';
import { MarketplaceStats } from '@/components/marketplace/MarketplaceStats';
import { MarketplaceFilters } from '@/components/marketplace/MarketplaceFilters';
import { MarketplaceProductCard } from '@/components/marketplace/MarketplaceProductCard';
import { ProductModal } from '@/components/marketplace/modals/ProductModal';
import { DeleteModal } from '@/components/marketplace/modals/DeleteModal';
import { ConfirmActionModal } from '@/components/marketplace/modals/ConfirmActionModal';
import { ProductReviewsModal } from '@/components/marketplace/modals/ProductReviewsModal';
import { MarketplaceLoading } from '@/components/marketplace/MarketplaceLoading';
import { type MarketplaceProduct } from '@/types/marketplace';

export default function AdminMarketplace() {
  const [selectedReviewsProduct, setSelectedReviewsProduct] = useState<MarketplaceProduct | null>(null);
  const {
    filtered,
    products,
    searchTerm,
    setSearchTerm,
    filterType,
    setFilterType,
    loading,
    isProcessing,
    totalActive,
    totalInactive,
    outOfStock,
    showModal,
    setShowModal,
    modalMode,
    editingProduct,
    editInitialData,
    editInitialMediaItems,
    editInitialShapeAttributes,
    openCreate,
    openEdit,
    handleSave,
    pendingSave,
    setPendingSave,
    confirmSave,
    pendingVisibility,
    setPendingVisibility,
    toggleActive,
    confirmToggleActive,
    deletingProduct,
    setDeletingProduct,
    confirmDelete,
  } = useAdminMarketplace();

  if (loading && products.length === 0) {
    return <MarketplaceLoading isAdmin={true} />;
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        {/* Encabezado */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-semibold text-primary mb-2">Gestión del Marketplace</h1>
            <p className="text-muted-foreground">
              Vista del marketplace para administradores con control de visibilidad y administración de productos.
            </p>
          </div>
        </div>

        {/* Estadísticas rápidas */}
        <MarketplaceStats
          totalActive={totalActive}
          totalInactive={totalInactive}
          outOfStock={outOfStock}
        />

        {/* Filtros */}
        <MarketplaceFilters
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          filterType={filterType}
          onFilterChange={setFilterType}
        />

        {/* Grid de productos */}
        {filtered.length === 0 ? (
          <Card>
            <CardContent className="py-16 text-center">
              <p className="text-muted-foreground text-sm">
                No se encontraron productos
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {filtered.map((product, idx) => (
              <MarketplaceProductCard
                key={product.id}
                product={product}
                onToggleActive={toggleActive}
                onEdit={openEdit}
                onDelete={setDeletingProduct}
                onViewReviews={setSelectedReviewsProduct}
                showEditAction={false}
                imageLoading={idx === 0 ? 'eager' : 'lazy'}
              />
            ))}
          </div>
        )}

        {/* Pie de página con conteo */}
        {filtered.length > 0 && (
          <p className="text-xs text-muted-foreground text-center">
            Mostrando{' '}
            <span className="font-semibold text-foreground">{filtered.length}</span>{' '}
            de{' '}
            <span className="font-semibold text-foreground">{products.length}</span>{' '}
            productos
          </p>
        )}
      </main>

      {/* Modal crear / editar */}
      {showModal && (
        <ProductModal
          mode={modalMode}
          initialData={editInitialData}
          initialMediaItems={editInitialMediaItems}
          initialShapeAttributes={editInitialShapeAttributes}
          onClose={() => setShowModal(false)}
          onSave={handleSave}
        />
      )}

      {pendingSave && (
        <ConfirmActionModal
          title={modalMode === 'create' ? 'Confirmar nuevo producto' : 'Confirmar cambios'}
          description={
            modalMode === 'create'
              ? 'Se creará un nuevo producto en el marketplace con la información diligenciada.'
              : 'Se guardarán los cambios realizados a este producto.'
          }
          confirmLabel={modalMode === 'create' ? 'Crear producto' : 'Guardar cambios'}
          onConfirm={confirmSave}
          onCancel={() => setPendingSave(null)}
          loading={isProcessing}
        />
      )}

      {pendingVisibility && (
        <ConfirmActionModal
          title={pendingVisibility.isPublic ? 'Desactivar producto' : 'Activar producto'}
          description={
            pendingVisibility.isPublic
              ? `"${pendingVisibility.name}" dejará de mostrarse en el marketplace público.`
              : `"${pendingVisibility.name}" volverá a mostrarse en el marketplace público.`
          }
          confirmLabel={pendingVisibility.isPublic ? 'Desactivar' : 'Activar'}
          onConfirm={confirmToggleActive}
          onCancel={() => setPendingVisibility(null)}
          loading={isProcessing}
        />
      )}

      {/* Modal confirmación de eliminación */}
      {deletingProduct && (
        <DeleteModal
          productName={deletingProduct.name}
          onConfirm={confirmDelete}
          onCancel={() => setDeletingProduct(null)}
          loading={isProcessing}
        />
      )}

      {selectedReviewsProduct && (
        <ProductReviewsModal
          open={Boolean(selectedReviewsProduct)}
          onOpenChange={(nextOpen) => {
            if (!nextOpen) {
              setSelectedReviewsProduct(null);
            }
          }}
          productId={Number(selectedReviewsProduct.id)}
          productTitle={selectedReviewsProduct.name}
          summaryRating={selectedReviewsProduct.rating}
          summaryReviews={selectedReviewsProduct.reviews}
          allowReview={false}
        />
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import {
  TrendingUp,
  DollarSign,
  ShoppingCart,
  CheckCircle,
  Percent,
  Receipt,
} from "lucide-react";

import Header from "@/components/Header";
import { SalesFilterBar } from "@/components/admin/sales/SalesFilterBar";
import { MetricCard } from "@/components/admin/sales/MetricCard";
import { SalesChart } from "@/components/admin/sales/SalesChart";
import { TransactionsTable } from "@/components/admin/sales/TransactionsTable";

import {
  fetchSalesSummary,
  fetchSalesChart,
  fetchTransactions,
  type TimeFilter,
  type SalesSummary,
  type ChartDataPoint,
  type TransactionItem,
} from "@/services/salesService";

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatCOP(value: number): string {
  return new Intl.NumberFormat("es-CO", {
    style: "currency",
    currency: "COP",
    maximumFractionDigits: 0,
  }).format(value);
}

function formatPercent(value: number): string {
  return `${value.toFixed(1)}%`;
}

const PAGE_SIZE = 20;

// ─── Page Component ───────────────────────────────────────────────────────────

export default function VentasPage() {
  // ── Filters & pagination ──
  const [filter, setFilter] = useState<TimeFilter>("month");
  const [statusFilter, setStatusFilter] = useState<"" | "approved" | "pending">("");
  const [offset, setOffset] = useState(0);

  // ── Data ──
  const [summary, setSummary] = useState<SalesSummary | null>(null);
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);
  const [transactions, setTransactions] = useState<TransactionItem[]>([]);
  const [totalTransactions, setTotalTransactions] = useState(0);

  // ── Loading / error ──
  const [summaryLoading, setSummaryLoading] = useState(true);
  const [chartLoading, setChartLoading] = useState(true);
  const [txLoading, setTxLoading] = useState(true);
  const [summaryError, setSummaryError] = useState("");
  const [chartError, setChartError] = useState("");
  const [txError, setTxError] = useState("");

  // ── Effect: summary + chart (reload on filter change) ──
  useEffect(() => {
    let cancelled = false;

    async function loadOverview() {
      setSummaryLoading(true);
      setChartLoading(true);
      setSummaryError("");
      setChartError("");

      try {
        const [summaryRes, chartRes] = await Promise.all([
          fetchSalesSummary(filter),
          fetchSalesChart(filter),
        ]);
        if (!cancelled) {
          setSummary(summaryRes);
          setChartData(chartRes.data);
        }
      } catch (err: unknown) {
        if (!cancelled) {
          const msg =
            (err as { response?: { data?: { detail?: string } } })?.response?.data?.detail ??
            "No se pudo cargar la información de ventas.";
          setSummaryError(msg);
          setChartError(msg);
        }
      } finally {
        if (!cancelled) {
          setSummaryLoading(false);
          setChartLoading(false);
        }
      }
    }

    loadOverview();
    return () => { cancelled = true; };
  }, [filter]);

  // ── Effect: transactions (reload on filter, statusFilter, offset change) ──
  useEffect(() => {
    let cancelled = false;

    async function loadTransactions() {
      setTxLoading(true);
      setTxError("");

      try {
        const res = await fetchTransactions({
          filter,
          status: statusFilter || undefined,
          limit: PAGE_SIZE,
          offset,
        });
        if (!cancelled) {
          setTransactions(res.items);
          setTotalTransactions(res.total);
        }
      } catch (err: unknown) {
        if (!cancelled) {
          const msg =
            (err as { response?: { data?: { detail?: string } } })?.response?.data?.detail ??
            "No se pudo cargar las transacciones.";
          setTxError(msg);
        }
      } finally {
        if (!cancelled) {
          setTxLoading(false);
        }
      }
    }

    loadTransactions();
    return () => { cancelled = true; };
  }, [filter, statusFilter, offset]);

  // Reset offset when filters change
  const handleFilterChange = useCallback((f: TimeFilter) => {
    setFilter(f);
    setOffset(0);
  }, []);

  const handleStatusFilterChange = useCallback((s: "" | "approved" | "pending") => {
    setStatusFilter(s);
    setOffset(0);
  }, []);

  const globalError = summaryError || chartError || txError;

  // ── Metric cards data ──
  const metrics = [
    {
      id: "total-ventas",
      title: "Total Ventas",
      value: summary ? formatCOP(summary.total_ventas) : "—",
      subtitle: "Todas las transacciones del período",
      icon: <DollarSign />,
      accentColor: "bg-indigo-500",
    },
    {
      id: "total-ganancias",
      title: "Ganancias Netas",
      value: summary ? formatCOP(summary.total_ganancias) : "—",
      subtitle: "Margen sobre costo base",
      icon: <TrendingUp />,
      accentColor: "bg-emerald-500",
    },
    {
      id: "total-transacciones",
      title: "Transacciones",
      value: summary ? String(summary.total_transacciones) : "—",
      subtitle: `${summary?.transacciones_aprobadas ?? "—"} aprobadas`,
      icon: <ShoppingCart />,
      accentColor: "bg-violet-500",
    },
    {
      id: "tasa-aprobacion",
      title: "Tasa de Aprobación",
      value: summary ? formatPercent(summary.tasa_aprobacion) : "—",
      subtitle: `Ticket promedio: ${summary ? formatCOP(summary.ticket_promedio) : "—"}`,
      icon: <CheckCircle />,
      accentColor: "bg-amber-500",
    },
  ];

  return (
    <div className="min-h-screen bg-background text-foreground">
      <Header />

      <main className="mx-auto max-w-7xl space-y-8 px-4 py-8 sm:px-6 lg:px-8">
        {/* ── Page header ── */}
        <section className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground sm:text-4xl">
              Ventas &amp; Transacciones
            </h1>
            <p className="mt-1 text-sm text-muted-foreground">
              Monitorea el rendimiento financiero y el historial de transacciones de la plataforma.
            </p>
          </div>

          <SalesFilterBar value={filter} onChange={handleFilterChange} />
        </section>

        {/* ── Global error banner ── */}
        {globalError && (
          <div
            role="alert"
            className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-900/40 dark:bg-red-900/40 dark:text-red-400"
          >
            <Receipt className="mt-0.5 h-4 w-4 flex-shrink-0" />
            <span>{globalError}</span>
          </div>
        )}

        {/* ── Metric cards ── */}
        <section
          className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4"
          aria-label="Métricas de ventas"
        >
          {metrics.map((m) => (
            <MetricCard
              key={m.id}
              title={m.title}
              value={m.value}
              subtitle={m.subtitle}
              icon={m.icon}
              accentColor={m.accentColor}
              loading={summaryLoading}
            />
          ))}
        </section>

        {/* ── Sales chart ── */}
        <section aria-label="Gráfica de ventas">
          <SalesChart data={chartData} loading={chartLoading} />
        </section>

        {/* ── Transactions table ── */}
        <section aria-label="Tabla de transacciones">
          {txError ? (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-900/40 dark:bg-red-900/40 dark:text-red-400">
              {txError}
            </div>
          ) : (
            <TransactionsTable
              items={transactions}
              total={totalTransactions}
              loading={txLoading}
              statusFilter={statusFilter}
              onStatusFilterChange={handleStatusFilterChange}
              offset={offset}
              limit={PAGE_SIZE}
              onPrev={() => setOffset((o) => Math.max(0, o - PAGE_SIZE))}
              onNext={() => setOffset((o) => o + PAGE_SIZE)}
            />
          )}
        </section>
      </main>
    </div>
  );
}

