"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { CheckCircle2, Loader2, ShieldX } from "lucide-react";
import { toast } from "sonner";

import { completeGoogleAuth, getDashboardByRole } from "@/services/auth.service";
import { audioService } from "@/services/audio.service";

export default function GoogleCallbackClient() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [status, setStatus] = useState<"loading" | "done" | "error">("loading");
  const [message, setMessage] = useState("Espere un momento mientras completamos el inicio de sesión.");

  const mode = useMemo(() => searchParams.get("mode") || "login", [searchParams]);

  useEffect(() => {
    const code = searchParams.get("code");
    const error = searchParams.get("error") || searchParams.get("error_description");
    const fallbackRoute = mode === "register" ? "/register" : "/login";
    const currentPath = `${window.location.pathname}${window.location.search}${window.location.hash}`;
    const hasFragment = window.location.hash.length > 1;

    console.log("Google callback received", { currentPath, mode, codePresent: Boolean(code), error, hasFragment });

    if (error) {
      const errorMessage = `No se pudo completar el inicio con Google: ${error}`;
      localStorage.setItem("google_auth_error", errorMessage);
      toast.error(errorMessage);
      setStatus("error");
      setMessage("Volveremos al formulario para que puedas intentarlo de nuevo.");
      router.replace(fallbackRoute);
      return;
    }

    if (!code && !hasFragment) {
      const errorMessage = "No se recibió el código de Google. Revisa que Supabase tenga autorizado este callback.";
      localStorage.setItem("google_auth_error", errorMessage);
      toast.error(errorMessage);
      setStatus("error");
      setMessage("Volveremos al formulario para que puedas intentarlo de nuevo.");
      router.replace(fallbackRoute);
      return;
    }

    let active = true;

    const finishOAuth = async () => {
      try {
        setStatus("loading");
        setMessage("Validando tu cuenta con Supabase y creando tu sesión...");
        const authResult = await completeGoogleAuth(code || undefined);

        if (!active) return;
        audioService.playLoginBell();

        const redirectPath = localStorage.getItem("redirect_after_login");
        if (redirectPath) {
          localStorage.removeItem("redirect_after_login");
          setStatus("done");
          router.replace(redirectPath);
          return;
        }

        setStatus("done");
        setMessage("Tu sesión quedó lista. Estamos entrando a tu panel.");
        router.replace(getDashboardByRole(authResult.role));
      } catch (err: unknown) {
        if (!active) return;

        console.error("finishOAuth error:", err);
        setStatus("error");
        const errorMessage = "No se pudo completar el inicio con Google. Puedes reintentar desde el formulario.";
        setMessage(errorMessage);
        localStorage.setItem("google_auth_error", errorMessage);
        toast.error(errorMessage);
        router.replace(fallbackRoute);
      }
    };

    void finishOAuth();

    return () => {
      active = false;
    };
  }, [mode, router, searchParams]);

  return (
    <div className="relative min-h-screen overflow-hidden bg-gradient-to-b from-background via-background to-muted/20">
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <div className="absolute left-[-8rem] top-[-8rem] h-72 w-72 rounded-full bg-accent/10 blur-3xl" />
        <div className="absolute right-[-6rem] top-24 h-80 w-80 rounded-full bg-accent-magenta/10 blur-3xl" />
      </div>

      <div className="relative flex min-h-screen items-center justify-center px-4 py-10 sm:px-6 lg:px-8">
        <div className="w-full max-w-lg rounded-[2rem] border border-border/60 bg-card/90 p-8 text-center shadow-[0_24px_80px_-44px_rgba(15,23,42,0.55)] backdrop-blur-md">
          <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl bg-gradient-to-br from-accent to-accent-magenta shadow-sm">
            {status === "error" ? (
              <ShieldX className="h-8 w-8 text-white" />
            ) : status === "done" ? (
              <CheckCircle2 className="h-8 w-8 text-white" />
            ) : (
              <Loader2 className="h-8 w-8 animate-spin text-white" />
            )}
          </div>

          <div className="mt-6 space-y-3">
            <p className="text-xs font-medium uppercase tracking-[0.22em] text-muted-foreground">
              Autenticación con Google
            </p>
            <h1 className="text-2xl font-semibold tracking-tight text-primary sm:text-3xl">
              {status === "error"
                ? "Volviendo al formulario"
                : status === "done"
                  ? "Sesión completada"
                  : "Completando el inicio de sesión"}
            </h1>
            <p className="text-sm leading-6 text-muted-foreground sm:text-base">
              {message}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import {
  TrendingUp,
  DollarSign,
  ShoppingCart,
  CheckCircle,
  Percent,
  Receipt,
} from "lucide-react";

import Header from "@/components/Header";
import { SalesFilterBar } from "@/components/admin/sales/SalesFilterBar";
import { MetricCard } from "@/components/admin/sales/MetricCard";
import { SalesChart } from "@/components/admin/sales/SalesChart";
import { TransactionsTable } from "@/components/admin/sales/TransactionsTable";

import {
  fetchCompanySalesSummary,
  fetchCompanySalesChart,
  fetchCompanyTransactions,
  type TimeFilter,
  type SalesSummary,
  type ChartDataPoint,
  type TransactionItem,
} from "@/services/salesService";

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatCOP(value: number): string {
  return new Intl.NumberFormat("es-CO", {
    style: "currency",
    currency: "COP",
    maximumFractionDigits: 0,
  }).format(value);
}

function formatPercent(value: number): string {
  return `${value.toFixed(1)}%`;
}

const PAGE_SIZE = 20;

// ─── Page Component ───────────────────────────────────────────────────────────

export default function FuncionarioVentasPage() {
  // ── Filters & pagination ──
  const [filter, setFilter] = useState<TimeFilter>("month");
  const [statusFilter, setStatusFilter] = useState<"" | "approved" | "pending">("");
  const [offset, setOffset] = useState(0);

  // ── Data ──
  const [summary, setSummary] = useState<SalesSummary | null>(null);
  const [chartData, setChartData] = useState<ChartDataPoint[]>([]);
  const [transactions, setTransactions] = useState<TransactionItem[]>([]);
  const [totalTransactions, setTotalTransactions] = useState(0);

  // ── Loading / error ──
  const [summaryLoading, setSummaryLoading] = useState(true);
  const [chartLoading, setChartLoading] = useState(true);
  const [txLoading, setTxLoading] = useState(true);
  const [summaryError, setSummaryError] = useState("");
  const [chartError, setChartError] = useState("");
  const [txError, setTxError] = useState("");

  // ── Effect: summary + chart (reload on filter change) ──
  useEffect(() => {
    let cancelled = false;

    async function loadOverview() {
      setSummaryLoading(true);
      setChartLoading(true);
      setSummaryError("");
      setChartError("");

      try {
        const [summaryRes, chartRes] = await Promise.all([
          fetchCompanySalesSummary(filter),
          fetchCompanySalesChart(filter),
        ]);
        if (!cancelled) {
          setSummary(summaryRes);
          setChartData(chartRes.data);
        }
      } catch (err: unknown) {
        if (!cancelled) {
          const msg =
            (err as { response?: { data?: { detail?: string } } })?.response?.data?.detail ??
            "No se pudo cargar la información de ventas.";
          setSummaryError(msg);
          setChartError(msg);
        }
      } finally {
        if (!cancelled) {
          setSummaryLoading(false);
          setChartLoading(false);
        }
      }
    }

    loadOverview();
    return () => { cancelled = true; };
  }, [filter]);

  // ── Effect: transactions (reload on filter, statusFilter, offset change) ──
  useEffect(() => {
    let cancelled = false;

    async function loadTransactions() {
      setTxLoading(true);
      setTxError("");

      try {
        const res = await fetchCompanyTransactions({
          filter,
          status: statusFilter || undefined,
          limit: PAGE_SIZE,
          offset,
        });
        if (!cancelled) {
          setTransactions(res.items);
          setTotalTransactions(res.total);
        }
      } catch (err: unknown) {
        if (!cancelled) {
          const msg =
            (err as { response?: { data?: { detail?: string } } })?.response?.data?.detail ??
            "No se pudo cargar las transacciones.";
          setTxError(msg);
        }
      } finally {
        if (!cancelled) {
          setTxLoading(false);
        }
      }
    }

    loadTransactions();
    return () => { cancelled = true; };
  }, [filter, statusFilter, offset]);

  // Reset offset when filters change
  const handleFilterChange = useCallback((f: TimeFilter) => {
    setFilter(f);
    setOffset(0);
  }, []);

  const handleStatusFilterChange = useCallback((s: "" | "approved" | "pending") => {
    setStatusFilter(s);
    setOffset(0);
  }, []);

  const globalError = summaryError || chartError || txError;

  // ── Metric cards data ──
  const metrics = [
    {
      id: "total-ventas",
      title: "Total Ventas",
      value: summary ? formatCOP(summary.total_ventas) : "—",
      subtitle: "Ventas de tu empresa en el período",
      icon: <DollarSign />,
      accentColor: "bg-indigo-500",
    },
    {
      id: "total-transacciones",
      title: "Transacciones",
      value: summary ? String(summary.total_transacciones) : "—",
      subtitle: `${summary?.transacciones_aprobadas ?? "—"} aprobadas`,
      icon: <ShoppingCart />,
      accentColor: "bg-violet-500",
    },
    {
      id: "tasa-aprobacion",
      title: "Tasa de Aprobación",
      value: summary ? formatPercent(summary.tasa_aprobacion) : "—",
      subtitle: `Ticket promedio: ${summary ? formatCOP(summary.ticket_promedio) : "—"}`,
      icon: <CheckCircle />,
      accentColor: "bg-amber-500",
    },
  ];

  return (
    <div className="min-h-screen bg-background text-foreground">
      <Header />

      <main className="mx-auto max-w-7xl space-y-8 px-4 py-8 sm:px-6 lg:px-8">
        {/* ── Page header ── */}
        <section className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground sm:text-4xl">
              Ventas de mi Empresa
            </h1>
            <p className="mt-1 text-sm text-muted-foreground">
              Monitorea el rendimiento financiero y el historial de transacciones de tus productos.
            </p>
          </div>

          <SalesFilterBar value={filter} onChange={handleFilterChange} />
        </section>

        {/* ── Global error banner ── */}
        {globalError && (
          <div
            role="alert"
            className="flex items-start gap-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-900/40 dark:bg-red-900/40 dark:text-red-400"
          >
            <Receipt className="mt-0.5 h-4 w-4 flex-shrink-0" />
            <span>{globalError}</span>
          </div>
        )}

        {/* ── Metric cards ── */}
        <section
          className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4"
          aria-label="Métricas de ventas"
        >
          {metrics.map((m) => (
            <MetricCard
              key={m.id}
              title={m.title}
              value={m.value}
              subtitle={m.subtitle}
              icon={m.icon}
              accentColor={m.accentColor}
              loading={summaryLoading}
            />
          ))}
        </section>

        {/* ── Sales chart ── */}
        <section aria-label="Gráfica de ventas">
          <SalesChart data={chartData} loading={chartLoading} hideProfits={true} />
        </section>

        {/* ── Transactions table ── */}
        <section aria-label="Tabla de transacciones">
          {txError ? (
            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700 dark:border-red-900/40 dark:bg-red-900/40 dark:text-red-400">
              {txError}
            </div>
          ) : (
            <TransactionsTable
              items={transactions}
              total={totalTransactions}
              loading={txLoading}
              statusFilter={statusFilter}
              onStatusFilterChange={handleStatusFilterChange}
              offset={offset}
              limit={PAGE_SIZE}
              onPrev={() => setOffset((o) => Math.max(0, o - PAGE_SIZE))}
              onNext={() => setOffset((o) => o + PAGE_SIZE)}
            />
          )}
        </section>
      </main>
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { ChevronLeft, ChevronRight, Clock } from 'lucide-react';
import { addDays, addWeeks, format, isSameDay, startOfWeek, subWeeks } from 'date-fns';
import { es } from 'date-fns/locale';
import { toast } from 'sonner';

import Header from '@/components/Header';
import { OrderDetailsModal } from '@/components/modals/OrderDetailsModal';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { funcionarioOrderService } from '@/services/funcionario-order.service';
import { type AdminOrder } from '@/types/order';

type CalendarView = 'week' | 'day';

type TimedOrder = AdminOrder & {
  assignedHour: number;
};

const WORK_HOURS_START = 8;
const WORK_HOURS_END = 18;
const TIME_SLOTS = Array.from({ length: WORK_HOURS_END - WORK_HOURS_START }, (_, i) => WORK_HOURS_START + i);

function getOrdersForDay(day: Date, orders: AdminOrder[]): AdminOrder[] {
  return orders.filter((order) => isSameDay(new Date(order.deliveryDate), day));
}

function distributeOrdersInDay(dayOrders: AdminOrder[]): TimedOrder[] {
  return dayOrders
    .slice()
    .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime())
    .map((order, index) => ({
      ...order,
      assignedHour: WORK_HOURS_START + (index % (WORK_HOURS_END - WORK_HOURS_START)),
    }));
}

function statusDot(status: AdminOrder['status']) {
  switch (status) {
    case 'En diseño':
      return 'bg-blue-500';
    case 'En producción':
      return 'bg-amber-500';
    case 'Listo para entregar':
      return 'bg-green-500';
    default:
      return 'bg-gray-400';
  }
}

function TimedOrderCard({ order, onClick }: { order: TimedOrder; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="w-full text-left p-2.5 rounded-lg border border-border bg-white hover:bg-muted/30 hover:shadow-sm transition"
    >
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="text-xs font-semibold truncate">{order.title}</p>
          <p className="text-[11px] text-muted-foreground truncate">{order.clientName || 'Cliente'}</p>
          <p className="text-[11px] mt-1 inline-flex items-center gap-1 text-muted-foreground">
            <Clock className="w-3 h-3" /> {order.assignedHour}:00
          </p>
        </div>
        <span className={`w-2.5 h-2.5 rounded-full mt-1 ${statusDot(order.status)}`} />
      </div>
    </button>
  );
}

function WeekGrid({ weekDays, orders, onOrderClick, today }: {
  weekDays: Date[];
  orders: AdminOrder[];
  onOrderClick: (id: string) => void;
  today: Date;
}) {
  return (
    <div className="min-w-[920px]">
      <div className="grid grid-cols-8 border-b border-border bg-muted/30">
        <div className="p-3 border-r border-border text-xs font-semibold text-muted-foreground">Hora</div>
        {weekDays.map((day) => (
          <div
            key={day.toISOString()}
            className={`p-3 border-r border-border text-center ${isSameDay(day, today) ? 'bg-accent/10' : ''}`}
          >
            <p className="text-xs font-medium capitalize">{format(day, 'EEE', { locale: es })}</p>
            <p className="text-lg font-semibold">{format(day, 'd')}</p>
          </div>
        ))}
      </div>

      {TIME_SLOTS.map((hour) => (
        <div key={hour} className="grid grid-cols-8 border-b border-border">
          <div className="p-3 border-r border-border text-xs text-muted-foreground">{hour}:00</div>
          {weekDays.map((day) => {
            const timed = distributeOrdersInDay(getOrdersForDay(day, orders));
            const atHour = timed.filter((o) => o.assignedHour === hour);

            return (
              <div key={`${day.toISOString()}-${hour}`} className="p-2 border-r border-border min-h-[88px]">
                <div className="space-y-1.5">
                  {atHour.map((order) => (
                    <TimedOrderCard key={order.id} order={order} onClick={() => onOrderClick(order.id)} />
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

function DayList({ date, orders, onOrderClick }: {
  date: Date;
  orders: AdminOrder[];
  onOrderClick: (id: string) => void;
}) {
  const timedOrders = useMemo(() => distributeOrdersInDay(getOrdersForDay(date, orders)), [date, orders]);

  return (
    <div>
      <div className="p-4 border-b border-border">
        <h3 className="font-semibold capitalize">{format(date, "EEEE, d 'de' MMMM yyyy", { locale: es })}</h3>
        <p className="text-sm text-muted-foreground">{timedOrders.length} pedidos programados</p>
      </div>

      {TIME_SLOTS.map((hour) => {
        const atHour = timedOrders.filter((o) => o.assignedHour === hour);
        return (
          <div key={hour} className="border-b border-border p-4">
            <div className="flex gap-4">
              <div className="w-16 text-sm text-muted-foreground">{hour}:00</div>
              <div className="flex-1 space-y-2">
                {atHour.length === 0 ? (
                  <p className="text-sm text-muted-foreground">Sin pedidos</p>
                ) : (
                  atHour.map((order) => (
                    <TimedOrderCard key={order.id} order={order} onClick={() => onOrderClick(order.id)} />
                  ))
                )}
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default function FuncionarioCalendario() {
  const [orders, setOrders] = useState<AdminOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [view, setView] = useState<CalendarView>('week');
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);

  useEffect(() => {
    const loadOrders = async () => {
      try {
        const data = await funcionarioOrderService.getOrders();
        setOrders(data);
      } catch (error: any) {
        toast.error(error?.message || 'No se pudieron cargar los pedidos del calendario');
      } finally {
        setLoading(false);
      }
    };

    loadOrders();
  }, []);

  const today = new Date();
  const weekStart = startOfWeek(currentDate, { weekStartsOn: 1 });
  const weekDays = Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));

  const goToPrev = () => setCurrentDate((d) => (view === 'week' ? subWeeks(d, 1) : addDays(d, -1)));
  const goToNext = () => setCurrentDate((d) => (view === 'week' ? addWeeks(d, 1) : addDays(d, 1)));
  const goToToday = () => setCurrentDate(new Date());

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-semibold text-primary mb-2">Calendario de Producción</h1>
            <p className="text-muted-foreground">Pedidos distribuidos automáticamente entre 8:00 y 18:00</p>
          </div>
          <div className="flex items-center gap-1 bg-muted rounded-lg p-1">
            <button
              type="button"
              onClick={() => setView('week')}
              className={`px-4 py-1.5 text-sm rounded-md ${view === 'week' ? 'bg-white shadow-sm font-medium text-black' : 'text-muted-foreground hover:text-black'}`}
            >
              Semana
            </button>
            <button
              type="button"
              onClick={() => setView('day')}
              className={`px-4 py-1.5 text-sm rounded-md ${view === 'day' ? 'bg-white shadow-sm font-medium text-black' : 'text-muted-foreground hover:text-black'}`}
            >
              Día
            </button>
          </div>
        </div>

        <Card>
          <CardContent className="pt-4 pb-4">
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-3">
                <Button variant="outline" size="icon" onClick={goToPrev}>
                  <ChevronLeft className="w-4 h-4" />
                </Button>
                <h2 className="text-base font-semibold capitalize min-w-[180px] text-center">
                  {view === 'week'
                    ? format(weekStart, 'MMMM yyyy', { locale: es })
                    : format(currentDate, "d 'de' MMMM yyyy", { locale: es })}
                </h2>
                <Button variant="outline" size="icon" onClick={goToNext}>
                  <ChevronRight className="w-4 h-4" />
                </Button>
              </div>
              <Button variant="outline" size="sm" onClick={goToToday}>
                Hoy
              </Button>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-4 pb-0 px-0 overflow-x-auto">
            {loading ? (
              <div className="py-16 text-center text-sm text-muted-foreground">Cargando calendario...</div>
            ) : view === 'week' ? (
              <WeekGrid weekDays={weekDays} orders={orders} onOrderClick={setSelectedOrderId} today={today} />
            ) : (
              <DayList date={currentDate} orders={orders} onOrderClick={setSelectedOrderId} />
            )}
          </CardContent>
        </Card>
      </main>

      {selectedOrderId && (
        <OrderDetailsModal
          orderId={selectedOrderId}
          isOpen={true}
          onClose={() => setSelectedOrderId(null)}
        />
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Plus } from 'lucide-react';

import Header from '@/components/Header';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';

import { useMarketplace } from '@/components/marketplace/hooks/useMarketplace';
import { MarketplaceStats } from '@/components/marketplace/MarketplaceStats';
import { MarketplaceFilters } from '@/components/marketplace/MarketplaceFilters';
import { MarketplaceProductCard } from '@/components/marketplace/MarketplaceProductCard';
import { ProductModal } from '@/components/marketplace/modals/ProductModal';
import { DeleteModal } from '@/components/marketplace/modals/DeleteModal';
import { ConfirmActionModal } from '@/components/marketplace/modals/ConfirmActionModal';
import { ProductReviewsModal } from '@/components/marketplace/modals/ProductReviewsModal';
import { MarketplaceLoading } from '@/components/marketplace/MarketplaceLoading';
import { type MarketplaceProduct } from '@/types/marketplace';

export default function FuncionarioMarketplace() {
  const [selectedReviewsProduct, setSelectedReviewsProduct] = useState<MarketplaceProduct | null>(null);
  const {
    filtered,
    products,
    searchTerm,
    setSearchTerm,
    filterType,
    setFilterType,
    loading,
    isProcessing,
    totalActive,
    totalInactive,
    outOfStock,
    showModal,
    setShowModal,
    modalMode,
    editingProduct,
    editInitialData,
    editInitialMediaItems,
    editInitialShapeAttributes,
    openCreate,
    openEdit,
    handleSave,
    pendingSave,
    setPendingSave,
    confirmSave,
    pendingVisibility,
    setPendingVisibility,
    toggleActive,
    confirmToggleActive,
    deletingProduct,
    setDeletingProduct,
    confirmDelete,
  } = useMarketplace();

  if (loading && products.length === 0) {
    return <MarketplaceLoading isAdmin={true} />;
  }

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        {/* Encabezado */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-semibold text-primary mb-2">
              Gestión del Marketplace
            </h1>
            <p className="text-muted-foreground">
              Agrega, edita y administra los productos disponibles
            </p>
          </div>
          <Button className="gap-2 w-full sm:w-auto" onClick={openCreate}>
            <Plus className="w-5 h-5" />
            Agregar Producto
          </Button>
        </div>

        {/* Estadísticas rápidas */}
        <MarketplaceStats
          totalActive={totalActive}
          totalInactive={totalInactive}
          outOfStock={outOfStock}
        />

        {/* Filtros */}
        <MarketplaceFilters
          searchTerm={searchTerm}
          onSearchChange={setSearchTerm}
          filterType={filterType}
          onFilterChange={setFilterType}
        />

        {/* Grid de productos */}
        {filtered.length === 0 ? (
          <Card>
            <CardContent className="py-16 text-center">
              <p className="text-muted-foreground text-sm">
                No se encontraron productos
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {filtered.map((product, idx) => (
              <MarketplaceProductCard
                key={product.id}
                product={product}
                onToggleActive={toggleActive}
                onEdit={openEdit}
                onDelete={setDeletingProduct}
                onViewReviews={setSelectedReviewsProduct}
                imageLoading={idx === 0 ? 'eager' : 'lazy'}
              />
            ))}
          </div>
        )}

        {/* Pie de página con conteo */}
        {filtered.length > 0 && (
          <p className="text-xs text-muted-foreground text-center">
            Mostrando{' '}
            <span className="font-semibold text-foreground">{filtered.length}</span>{' '}
            de{' '}
            <span className="font-semibold text-foreground">{products.length}</span>{' '}
            productos
          </p>
        )}
      </main>

      {/* Modal crear / editar */}
      {showModal && (
        <ProductModal
          mode={modalMode}
          initialData={editInitialData}
          initialMediaItems={editInitialMediaItems}
          initialShapeAttributes={editInitialShapeAttributes}
          onClose={() => setShowModal(false)}
          onSave={handleSave}
        />
      )}

      {pendingSave && (
        <ConfirmActionModal
          title={modalMode === 'create' ? 'Confirmar nuevo producto' : 'Confirmar cambios'}
          description={
            modalMode === 'create'
              ? 'Se creará un nuevo producto en el marketplace con la información diligenciada.'
              : 'Se guardarán los cambios realizados a este producto.'
          }
          confirmLabel={modalMode === 'create' ? 'Crear producto' : 'Guardar cambios'}
          onConfirm={confirmSave}
          onCancel={() => setPendingSave(null)}
          loading={isProcessing}
        />
      )}

      {pendingVisibility && (
        <ConfirmActionModal
          title={pendingVisibility.isPublic ? 'Desactivar producto' : 'Activar producto'}
          description={
            pendingVisibility.isPublic
              ? `"${pendingVisibility.name}" dejará de mostrarse en el marketplace público.`
              : `"${pendingVisibility.name}" volverá a mostrarse en el marketplace público.`
          }
          confirmLabel={pendingVisibility.isPublic ? 'Desactivar' : 'Activar'}
          onConfirm={confirmToggleActive}
          onCancel={() => setPendingVisibility(null)}
          loading={isProcessing}
        />
      )}

      {/* Modal confirmación de eliminación */}
      {deletingProduct && (
        <DeleteModal
          productName={deletingProduct.name}
          onConfirm={confirmDelete}
          onCancel={() => setDeletingProduct(null)}
          loading={isProcessing}
        />
      )}

      {selectedReviewsProduct && (
        <ProductReviewsModal
          open={Boolean(selectedReviewsProduct)}
          onOpenChange={(nextOpen) => {
            if (!nextOpen) {
              setSelectedReviewsProduct(null);
            }
          }}
          productId={Number(selectedReviewsProduct.id)}
          productTitle={selectedReviewsProduct.name}
          summaryRating={selectedReviewsProduct.rating}
          summaryReviews={selectedReviewsProduct.reviews}
          allowReview={false}
        />
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Header from '@/components/Header';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { OrderDetailsModal } from '@/components/modals/OrderDetailsModal';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { DataPagination } from '@/components/ui/DataPagination';
import { funcionarioOrderService } from '@/services/funcionario-order.service';
import { type AdminOrder } from '@/types/order';
import { Eye, Search, Sparkles, CheckCircle2, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

const PAGE_SIZE = 10;

export default function FuncionarioPedidosPendientesPage() {
  const [orders, setOrders] = useState<AdminOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [acceptingId, setAcceptingId] = useState<string | null>(null);
  const [pendingAcceptOrder, setPendingAcceptOrder] = useState<AdminOrder | null>(null);
  const [selectedOrderId, setSelectedOrderId] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setDebouncedSearch(search.trim());
      setPage(1);
    }, 250);

    return () => window.clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    const load = async () => {
      try {
        setLoading(true);
        const data = await funcionarioOrderService.getPendingCustomOrdersPage(
          {
            page,
            pageSize: PAGE_SIZE,
            search: debouncedSearch,
          },
          controller.signal,
        );

        if (cancelled || controller.signal.aborted) return;

        setOrders(data.items ?? []);
        setTotalPages(Math.max(1, data.totalPages ?? 1));
        setTotalItems(data.totalItems ?? 0);
      } catch (error: any) {
        if (cancelled || controller.signal.aborted) return;
        toast.error(error?.message || 'No se pudieron cargar los pedidos pendientes');
        setOrders([]);
        setTotalPages(1);
        setTotalItems(0);
      } finally {
        if (!cancelled && !controller.signal.aborted) {
          setLoading(false);
        }
      }
    };

    void load();

    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [page, debouncedSearch]);

  const handleAccept = async (orderId: string) => {
    try {
      setAcceptingId(orderId);
      const updated = await funcionarioOrderService.acceptPendingCustomOrder(orderId);
      setOrders((prev) => prev.filter((order) => order.id !== orderId));
      setPendingAcceptOrder((prev) => (prev?.id === orderId ? null : prev));
      toast.success(`Pedido #${orderId} aceptado y asignado a ${updated.companyName || 'tu empresa'}`);
    } catch (error: any) {
      toast.error(error?.message || 'No se pudo aceptar el pedido');
    } finally {
      setAcceptingId(null);
    }
  };

  const handleConfirmAccept = async () => {
    if (!pendingAcceptOrder) return;
    await handleAccept(pendingAcceptOrder.id);
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-background via-background to-muted/20">
      <Header />

      <main className="mx-auto max-w-7xl space-y-8 px-4 py-8 sm:px-6 lg:px-8">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-3xl space-y-2">
            <div className="inline-flex items-center gap-2 rounded-full border border-border bg-muted/40 px-3 py-1 text-xs font-medium uppercase tracking-[0.2em] text-muted-foreground">
              <Sparkles className="h-3.5 w-3.5 text-accent" />
              Nueva bandeja
            </div>
            <h1 className="text-3xl font-semibold tracking-tight text-primary sm:text-4xl">
              Pedidos pendientes
            </h1>
            <p className="text-sm text-muted-foreground sm:text-base">
              Aquí llegan los pedidos personalizados que todavía no tienen empresa asignada. Puedes revisarlos, abrir sus detalles y aceptarlos para convertirlos en pedidos de tu empresa.
            </p>
          </div>

          <Card className="border-border/60 bg-card/90 shadow-sm">
            <CardContent className="flex items-center gap-3 px-5 py-4">
              <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-accent/10 text-accent">
                <CheckCircle2 className="h-5 w-5" />
              </div>
              <div>
                <p className="text-xs uppercase tracking-[0.2em] text-muted-foreground">Pendientes</p>
                <p className="text-2xl font-semibold text-foreground">{totalItems}</p>
              </div>
            </CardContent>
          </Card>
        </div>

        <Card className="border-border/60 bg-card/90 shadow-sm">
          <CardContent className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between">
            <div className="relative w-full sm:max-w-xl">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Busca por pedido, cliente o shape..."
                className="w-full rounded-xl border border-border bg-transparent py-3 pl-10 pr-4 text-sm outline-none transition focus:border-accent"
              />
            </div>
            <p className="text-sm text-muted-foreground">
              Los pedidos aceptados desaparecen de esta bandeja y pasan a pendiente de pago.
            </p>
          </CardContent>
        </Card>

        {loading ? (
          <div className="rounded-3xl border border-border bg-card/90 p-12 text-center text-sm text-muted-foreground shadow-sm">
            Cargando pedidos pendientes...
          </div>
        ) : orders.length === 0 ? (
          <Card className="border-dashed border-border bg-card/80 shadow-sm">
            <CardContent className="flex min-h-[260px] flex-col items-center justify-center px-6 py-12 text-center">
              <div className="flex h-16 w-16 items-center justify-center rounded-full bg-muted/60 text-muted-foreground">
                <Sparkles className="h-7 w-7" />
              </div>
              <h3 className="mt-4 text-lg font-semibold text-foreground">No hay pedidos pendientes</h3>
              <p className="mt-2 max-w-xl text-sm text-muted-foreground">
                Cuando llegue un pedido personalizado nuevo, aparecerá aquí para que puedas revisarlo y asignarlo a tu empresa.
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid gap-4 xl:grid-cols-2">
            {orders.map((order) => (
              <Card key={order.id} className="border-border/60 bg-card/90 shadow-[0_16px_40px_-24px_rgba(15,23,42,0.45)] backdrop-blur-sm transition-transform duration-200 hover:-translate-y-0.5 hover:shadow-lg">
                <CardContent className="p-5">
                  <div className="flex flex-col gap-4 sm:flex-row">
                    <div className="relative h-28 w-full overflow-hidden rounded-2xl bg-muted/30 sm:w-28 sm:flex-shrink-0">
                      {order.imageUrl ? (
                        <img src={order.imageUrl} alt={order.title} className="h-full w-full object-cover" />
                      ) : (
                        <div className="flex h-full w-full items-center justify-center text-xs text-muted-foreground">
                          Sin imagen
                        </div>
                      )}
                    </div>

                    <div className="flex-1 space-y-3">
                      <div className="flex items-start justify-between gap-3">
                        <div>
                          <h3 className="text-lg font-semibold tracking-tight text-foreground">{order.title}</h3>
                          <p className="text-sm text-muted-foreground">Pedido #{order.id}</p>
                        </div>
                        <span className="inline-flex rounded-full bg-slate-100 px-3 py-1 text-xs font-medium text-slate-700">
                          {order.status}
                        </span>
                      </div>

                      <div className="grid gap-2 text-sm text-muted-foreground sm:grid-cols-2">
                        <p><span className="font-medium text-foreground">Cliente:</span> {order.clientName || 'Cliente'}</p>
                        <p><span className="font-medium text-foreground">Producto:</span> {order.productType || 'Personalizado'}</p>
                        <p><span className="font-medium text-foreground">Cantidad:</span> {order.quantity || 1}</p>
                        <p><span className="font-medium text-foreground">Entrega:</span> {new Date(order.deliveryDate).toLocaleDateString('es-ES')}</p>
                      </div>

                      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border pt-4">
                        <span className="text-xl font-semibold text-primary">${order.price.toLocaleString()}</span>
                        <div className="flex gap-2">
                          <Button variant="outline" size="sm" className="gap-2" onClick={() => setSelectedOrderId(order.id)}>
                            <Eye className="h-4 w-4" />
                            Ver detalles
                          </Button>
                          <Button
                            size="sm"
                            className="gap-2 bg-accent text-accent-foreground hover:bg-accent/90"
                            onClick={() => setPendingAcceptOrder(order)}
                            disabled={acceptingId === order.id}
                          >
                            {acceptingId === order.id ? (
                              <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                              <CheckCircle2 className="h-4 w-4" />
                            )}
                            {acceptingId === order.id ? 'Aceptando...' : 'Aceptar pedido'}
                          </Button>
                        </div>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {!loading && totalPages > 1 && (
          <DataPagination page={page} totalPages={totalPages} totalItems={totalItems} onPageChange={setPage} />
        )}
      </main>

      {selectedOrderId && (
        <OrderDetailsModal orderId={selectedOrderId} isOpen={true} onClose={() => setSelectedOrderId(null)} />
      )}

      <AlertDialog open={Boolean(pendingAcceptOrder)} onOpenChange={(open) => !open && setPendingAcceptOrder(null)}>
        <AlertDialogContent className="border-border bg-card text-foreground">
          <AlertDialogHeader>
            <AlertDialogTitle>¿Aceptar este pedido personalizado?</AlertDialogTitle>
            <AlertDialogDescription className="text-muted-foreground">
              Si confirmas, el pedido #{pendingAcceptOrder?.id} quedará asignado a tu empresa, el cliente recibirá aviso y después podrá continuar con el pago.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="rounded-xl border border-border bg-muted/30 p-4 text-sm text-muted-foreground">
            <p className="font-medium text-foreground">{pendingAcceptOrder?.title}</p>
            <p className="mt-1">Cliente: {pendingAcceptOrder?.clientName || 'Cliente'}</p>
            <p className="mt-1">Valor estimado: ${pendingAcceptOrder?.price.toLocaleString() || '0'}</p>
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-border bg-background text-foreground hover:bg-muted">
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmAccept}
              className="bg-accent text-accent-foreground hover:bg-accent/90"
            >
              {acceptingId === pendingAcceptOrder?.id ? 'Aceptando...' : 'Sí, aceptar pedido'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

'use client';

import Header from '@/components/Header';
import { Card } from '@/components/ui/card';
import { DataPagination } from '@/components/ui/DataPagination';

import { useFuncionarioPedidos } from '@/components/Pedidos/hooks/useFuncionarioPedidos';
import { OrdersFilters } from '@/components/Pedidos/funcionario/OrdersFilters';
import { OrdersTable } from '../../../components/Pedidos/funcionario/OrdersTable';
import { TableSkeleton } from '@/components/Pedidos/funcionario/TableSkeleton';
import { ConfirmStatusModal } from '@/components/Pedidos/modals/ConfirmStatusModal';

export default function FuncionarioPedidosPage() {
  const {
    inputSearch,
    handleSearchChange,
    isSearching,
    filterStatus,
    handleFilterChange,
    orders,
    loading,
    debouncedSearch,
    page,
    setPage,
    totalPages,
    totalItems,
    pendingChange,
    setPendingChange,
    handleStatusChange,
    confirmStatusChange,
  } = useFuncionarioPedidos();

  return (
    <div className="min-h-screen bg-background">
      <Header />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        <div>
          <h1 className="text-3xl font-semibold text-primary mb-2">Gestión de Pedidos</h1>
          <p className="text-muted-foreground">Ver, filtrar y actualizar el estado de todos los pedidos</p>
        </div>

        <OrdersFilters
          inputSearch={inputSearch}
          onSearchChange={handleSearchChange}
          filterStatus={filterStatus}
          onFilterChange={handleFilterChange}
          isSearching={isSearching}
        />

        <Card className="overflow-hidden p-0">
          {loading ? (
            <TableSkeleton />
          ) : orders.length === 0 ? (
            <div className="text-center py-16">
              <p className="text-muted-foreground text-sm">
                No se encontraron pedidos
                {debouncedSearch && (
                  <>
                    {' '}
                    con el término "<span className="font-medium">{debouncedSearch}</span>"
                  </>
                )}
              </p>
            </div>
          ) : (
            <OrdersTable
              orders={orders}
              totalItems={totalItems}
              onStatusChange={handleStatusChange}
            />
          )}
        </Card>

        {!loading && (
          <DataPagination
            page={page}
            totalPages={totalPages}
            totalItems={totalItems}
            onPageChange={setPage}
          />
        )}
      </main>

      {pendingChange && (
        <ConfirmStatusModal
          orderId={pendingChange.orderId}
          nextStatus={pendingChange.newStatus}
          onConfirm={confirmStatusChange}
          onCancel={() => setPendingChange(null)}
        />
      )}
    </div>
  );
}

import { Search } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { OrderStatus } from '@/components/Pedidos/types/pedido';

interface Props {
  searchTerm: string;
  setSearchTerm: (value: string) => void;
  filterStatus: OrderStatus | 'all';
  setFilterStatus: (value: OrderStatus | 'all') => void;
}

const statuses: (OrderStatus | 'all')[] = [
  'all',
  'Pendiente de pago',
  'En diseño',
  'En producción',
  'Listo para entregar',
  'Entregado',
];

export function PedidoFilters({
  searchTerm,
  setSearchTerm,
  filterStatus,
  setFilterStatus,
}: Props) {
  return (
    <Card>
      <div className="flex flex-col md:flex-row gap-4">
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
          <input
            type="text"
            placeholder="Buscar pedidos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-input-background border border-border rounded-lg focus:outline-none focus:ring-2 focus:ring-accent"
          />
        </div>

        <div className="flex items-center bg-muted/50 rounded-xl p-1 gap-1 overflow-x-auto scrollbar-hide">
          {statuses.map((status) => {
            const isActive = filterStatus === status;

            return (
              <button
                key={status}
                onClick={() => setFilterStatus(status)}
                className={`
                  px-4 py-2 text-sm rounded-lg transition-all whitespace-nowrap
                  ${isActive 
                    ? 'bg-background shadow-sm text-foreground font-medium' 
                    : 'text-muted-foreground hover:text-foreground'}
                `}
              >
                {status === 'all' ? 'Todos' : status}
              </button>
            );
          })}
        </div>
      </div>
    </Card>
  );
}

'use client';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { toast } from 'sonner';
import { funcionarioOrderService } from '@/services/funcionario-order.service';
import { AdminOrder, OrderStatus } from '@/types/order';
import {
    type FilterStatus,
    PAGE_SIZE,
    DEBOUNCE_MS,
    normalizeText,
} from '@/components/Pedidos/funcionario/pedidos-funcionario.types';
export function useFuncionarioPedidos() {
    const [inputSearch, setInputSearch] = useState('');
    const [debouncedSearch, setDebouncedSearch] = useState('');
    const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
    const [page, setPage] = useState(1);
    const [orders, setOrders] = useState<AdminOrder[]>([]);
    const [loading, setLoading] = useState(true);
    const [totalPages, setTotalPages] = useState(1);
    const [totalItems, setTotalItems] = useState(0);
    const [pendingChange, setPendingChange] = useState<{
        orderId: string;
        newStatus: OrderStatus;
    } | null>(null);
    const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const abortRef = useRef<AbortController | null>(null);
    const isSearching = useMemo(() => {
        return normalizeText(inputSearch) !== debouncedSearch;
    }, [inputSearch, debouncedSearch]);
    const handleSearchChange = useCallback((value: string) => {
        setInputSearch(value);
        if (timerRef.current) clearTimeout(timerRef.current);
        timerRef.current = setTimeout(() => {
            setDebouncedSearch(normalizeText(value));
            setPage(1);
        }, DEBOUNCE_MS);
    }, []);
    const handleFilterChange = useCallback((value: FilterStatus) => {
        setFilterStatus(value);
        setPage(1);
    }, []);
    useEffect(() => {
        if (abortRef.current) abortRef.current.abort();
        const controller = new AbortController();
        abortRef.current = controller;
        let cancelled = false;
        const load = async () => {
            setLoading(true);
            try {
                const data = await funcionarioOrderService.getFuncionarioOrdersPage(
                    {
                        page,
                        pageSize: PAGE_SIZE,
                        search: debouncedSearch,
                        status: filterStatus,
                    },
                    controller.signal,
                );
                if (cancelled || controller.signal.aborted) return;
                setOrders(data.items ?? []);
                setTotalPages(Math.max(1, data.totalPages ?? 1));
                setTotalItems(data.totalItems ?? 0);
            } catch (err: any) {
                if (err?.name === 'AbortError' || cancelled || controller.signal.aborted) return;
                toast.error(err?.message || 'No se pudieron cargar los pedidos');
                setOrders([]);
                setTotalPages(1);
                setTotalItems(0);
            } finally {
                if (!cancelled && !controller.signal.aborted) {
                    setLoading(false);
                }
            }
        };
        load();
        return () => {
            cancelled = true;
            controller.abort();
        };
    }, [page, debouncedSearch, filterStatus]);
    useEffect(() => {
        return () => {
            if (timerRef.current) clearTimeout(timerRef.current);
            if (abortRef.current) abortRef.current.abort();
        };
    }, []);
    const handleStatusChange = useCallback(
        (orderId: string, newStatus: OrderStatus) => {
            const order = orders.find((o) => o.id === orderId);
            if (!order || order.status === newStatus) return;
            setPendingChange({ orderId, newStatus });
        },
        [orders],
    );
    const confirmStatusChange = async () => {
        if (!pendingChange) return;
        const { orderId, newStatus } = pendingChange;
        try {
            const updated = await funcionarioOrderService.updateStatus(orderId, newStatus);
            setOrders((prev) => prev.map((o) => (o.id === orderId ? updated : o)));
            toast.success(`Pedido #${orderId} actualizado a "${updated.status}"`);
        } catch (err: any) {
            toast.error(err?.message || 'No se pudo actualizar el estado');
        } finally {
            setPendingChange(null);
        }
    };
    return {
        // Búsqueda
        inputSearch,
        handleSearchChange,
        isSearching,
        // Filtro
        filterStatus,
        handleFilterChange,
        // Datos
        orders,
        loading,
        debouncedSearch,
        // Paginación
        page,
        setPage,
        totalPages,
        totalItems,
        // Cambio de estado
        pendingChange,
        setPendingChange,
        handleStatusChange,
        confirmStatusChange,
    };
}

'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Pedido, OrderStatus } from '../types/pedido';
import { pedidosService } from '../services/pedidos.service';

const PAGE_SIZE = 10;
const DEBOUNCE_MS = 250;

function normalizeText(value: string) {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function canonicalStatus(value: string): OrderStatus {
  const s = normalizeText(value);

  if (s === 'pendiente') return 'Pendiente';
  if (s === 'en diseno') return 'En diseño';
  if (s === 'en produccion') return 'En producción';
  if (s === 'listo para entregar') return 'Listo para entregar';
  if (s === 'entregado') return 'Entregado';

  return value as OrderStatus;
}

export function usePedidos() {
  const [searchTerm, setSearchTermState] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [filterStatus, setFilterStatusState] = useState<OrderStatus | 'all'>('all');
  const [page, setPage] = useState(1);

  const [pedidos, setPedidos] = useState<Pedido[]>([]);
  const [loading, setLoading] = useState(true);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);

  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const handleSearchChange = useCallback((value: string) => {
    setSearchTermState(value);

    if (timerRef.current) clearTimeout(timerRef.current);

    timerRef.current = setTimeout(() => {
      const cleaned = normalizeText(value);
      setDebouncedSearch(cleaned);
      setPage(1);
    }, DEBOUNCE_MS);
  }, []);

  const handleFilterChange = useCallback((value: OrderStatus | 'all') => {
    setFilterStatusState(value);
    setPage(1);
  }, []);

  useEffect(() => {
    if (abortRef.current) abortRef.current.abort();

    const controller = new AbortController();
    abortRef.current = controller;

    let alive = true;

    const load = async () => {
      setLoading(true);

      try {
        const data = await pedidosService.getMyOrdersPage(
          {
            page,
            pageSize: PAGE_SIZE,
            search: debouncedSearch,
            status: filterStatus,
          },
          controller.signal,
        );

        if (!alive || controller.signal.aborted) return;

        const normalizedItems = (data.items ?? []).map((order: Pedido) => ({
          ...order,
          status: canonicalStatus(order.status),
        }));

        setPedidos(normalizedItems);
        setTotalPages(Math.max(1, data.totalPages ?? 1));
        setTotalItems(data.totalItems ?? 0);
      } catch (err: any) {
        if (err?.name === 'AbortError' || controller.signal.aborted || !alive) return;

        setPedidos([]);
        setTotalPages(1);
        setTotalItems(0);
      } finally {
        if (alive && !controller.signal.aborted) {
          setLoading(false);
        }
      }
    };

    load();

    return () => {
      alive = false;
      controller.abort();
    };
  }, [page, debouncedSearch, filterStatus]);

  useEffect(() => {
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  const isSearching = useMemo(() => {
    return normalizeText(searchTerm) !== debouncedSearch;
  }, [searchTerm, debouncedSearch]);

  return {
    searchTerm,
    setSearchTerm: handleSearchChange,
    filterStatus,
    setFilterStatus: handleFilterChange,
    filteredPedidos: pedidos,
    loading,
    isSearching,
    page,
    setPage,
    totalPages,
    totalItems,
  };
}

