      });

      // 🔥 LIMPIAR TODO
      reset();

      toast.success("Pedido creado. Quedará pendiente hasta que una empresa lo acepte.");
      router.push("/cliente/pedidos");
    } catch (error) {
      const message = error instanceof Error ? error.message : "Error al crear pedido";

