          </div>

          {isCliente ? (
            <Link href="/cliente/crear-pedido">
              <Button><Plus /> Crear Pedido</Button>
            </Link>
          ) : (
            <Link href="/funcionario/pedidos-pendientes">
              <Button>Pedidos Pendientes</Button>
            </Link>
          )}
        </div>

        {/* STATS */}
        {isCliente ? (
          <div className="grid w-full gap-6 md:grid-cols-2 xl:grid-cols-4">
            <StatCard label="Pendientes de pago" value={stats.pending_payment} icon={<Clock />} colorClass="bg-rose-100 text-rose-600 dark:bg-rose-900/40 dark:text-rose-400" />
            <StatCard label="Activos" value={stats.active} icon={<Package />} colorClass="bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-400" />
            <StatCard label="Pendientes de entrega" value={stats.ready} icon={<CheckCircle />} colorClass="bg-amber-100 text-amber-600 dark:bg-amber-900/40 dark:text-amber-400" />
            <StatCard label="Totales" value={stats.total} icon={<TrendingUp />} colorClass="bg-green-100 text-green-600 dark:bg-green-900/40 dark:text-green-400" />
          </div>
        ) : (
          <div className="grid w-full gap-6 md:grid-cols-2 xl:grid-cols-4">
            <StatCard label="En Diseño" value={stats.design} icon={<AlertCircle />} colorClass="bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-400" />
            <StatCard label="En Producción" value={stats.production} icon={<Clock />} colorClass="bg-amber-100 text-amber-600 dark:bg-amber-900/40 dark:text-amber-400" />
            <StatCard label="Listo para entregar" value={stats.ready} icon={<CheckCircle />} colorClass="bg-green-100 text-green-600 dark:bg-green-900/40 dark:text-green-400" />
            <StatCard label="Total Pedidos" value={stats.total} icon={<Package />} colorClass="bg-purple-100 text-purple-600 dark:bg-purple-900/40 dark:text-purple-400" />
          </div>
        )}

        {/* ACCESOS RÁPIDOS */}
        <section>
          <h2 className="mb-4 text-xl font-semibold">Accesos Rápidos</h2>

          <div className="mx-auto grid w-full max-w-5xl grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {isCliente ? (
              <>
                <QuickActionCard
                  href="/cliente/crear-pedido"
                  icon={<Plus className="w-5 h-5 text-white" />}
                  iconBg="bg-gradient-to-br from-accent to-accent-magenta"
                  title="Crear Pedido"
                  description="Diseña un producto personalizado con IA"
                />

                <QuickActionCard
                  href="/marketplace"
                  icon={<ShoppingBag className="w-5 h-5 text-primary" />}
                  iconBg="bg-primary/10"
                  title="Marketplace"
                  description="Explora productos listos"
                />

                <QuickActionCard
                  href="/cliente/pedidos"
                  icon={<Package className="w-5 h-5 text-primary" />}
                  iconBg="bg-primary/10"
                  title="Mis Pedidos"
                  description="Ver historial"
                />

                {!hasCompany && (
                  <QuickActionCard
                    href="/crear-empresa"
                    icon={<Store className="w-5 h-5 text-primary" />}
                    iconBg="bg-primary/10"
                    title="Vende tus productos"
                    description="Registra tu empresa y empieza a vender"
                  />
                )}
              </>
            ) : (
              <>
                <QuickActionCard
                  href="/funcionario/pedidos"
                  icon={<Package className="w-5 h-5 text-primary" />}
                  iconBg="bg-primary/10"
                  title="Gestionar Pedidos"
                  description="Actualizar estados"
                />

                <QuickActionCard
                  href="/funcionario/pedidos-pendientes"
                  icon={<Clock className="w-5 h-5 text-primary" />}
                  iconBg="bg-primary/10"
                  title="Pedidos Pendientes"
                  description="Asignar pedidos personalizados"
                />

                <QuickActionCard
                  href="/funcionario/marketplace"
                  icon={<ShoppingBag className="w-5 h-5 text-primary" />}
                  iconBg="bg-primary/10"
                  title="Gestionar Marketplace"
                  description="Administrar productos"
                />
              </>
            )}
          </div>
        </section>

        {/* LISTA */}
        <section>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-semibold">
              {isCliente ? 'Pedidos Recientes' : 'Pedidos Urgentes'}
            </h2>

            <Link href={isCliente ? '/cliente/pedidos' : '/funcionario/pedidos'}>
              <Button variant="ghost" size="sm">
                Ver todos
              </Button>
            </Link>
          </div>

          <div className="space-y-4">
            {orders.slice(0, 3).map((order) =>
              isCliente ? (
                <OrderCard key={order.id} order={order as BaseOrder} />
              ) : (
                <UrgentOrderCard key={order.id} order={order as AdminOrder} />
              )
            )}
          </div>
        </section>
      </main>
    </div>
  );
}

