// /components/marketplace/Marketplace.tsx
'use client';

import { useState, useEffect } from 'react';
import { useProducts } from '@/hooks/useProducts';
import { ProductType, Product } from '@/types/product';
import { Filters } from './Filters';
import { ProductCard } from './ProductCard';
import { BuyOrderModal } from './modals/BuyOrderModal';
import { ConfirmBuyModal } from './modals/ConfirmBuyModal';
import { useMarketplaceBuy } from './hooks/useMarketplaceBuy';
import { useRouter, useSearchParams } from 'next/navigation';
import { ProductReviewsModal } from './modals/ProductReviewsModal';
import { MarketplaceLoading } from './MarketplaceLoading';

export const Marketplace = () => {
  const { products, loading: productsLoading } = useProducts();
  const router = useRouter();
  const searchParams = useSearchParams();
  const { attrValues, errors, loading, quantity, setQuantity, initAttributes, setField, createOrder, resetForm, validateForm } =
    useMarketplaceBuy();

  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<ProductType | 'all'>('all');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedReviewsProduct, setSelectedReviewsProduct] = useState<Product | null>(null);
  const [showBuyModal, setShowBuyModal] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [hasToken, setHasToken] = useState(false);

  useEffect(() => {
    const typeParam = searchParams.get('type');
    if (typeParam) {
      setFilterType(typeParam as ProductType);
    }
  }, [searchParams]);

  useEffect(() => {
    setHasToken(Boolean(localStorage.getItem('token')));
  }, []);

  if (productsLoading) {
    return <MarketplaceLoading isAdmin={false} />;
  }

  const filtered = products.filter((p) => {
    const matchesSearch =
      p.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.description.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesFilter =
      filterType === 'all' || p.productType === filterType;

    return matchesSearch && matchesFilter;
  });

  const handleBuy = (product: Product) => {
    const token = localStorage.getItem('token');

    if (!token) {
      localStorage.setItem('redirect_after_login', '/marketplace');
      router.push('/login');
      return;
    }

    resetForm();
    setSelectedProduct(product);
    setQuantity(1);
    setShowBuyModal(true);
  };

  const handleViewReviews = (product: Product) => {
    setSelectedReviewsProduct(product);
  };

  const handleBuyConfirm = () => {
    if (!selectedProduct) return;
    const isValid = validateForm(selectedProduct.attributes, selectedProduct.stock);
    if (!isValid) return;

    setShowBuyModal(false);
    setShowConfirmModal(true);
  };

  // ✅ CONFIRMAR Y CREAR ORDEN (incluye check de token)
  const handleFinalConfirm = async () => {
    if (!selectedProduct) return;

    const success = await createOrder(
      selectedProduct.id,
      selectedProduct.title,
      selectedProduct.attributes,
      selectedProduct.stock
    );

    if (success) {
      setShowConfirmModal(false);
      resetForm();
      setSelectedProduct(null);
    }
  };

  const handleCloseBuyModal = () => {
    setShowBuyModal(false);
  };

  const handleCloseConfirmModal = () => {
    setShowConfirmModal(false);
    setShowBuyModal(true);
  };

  return (
    <div className="px-4 sm:px-6 lg:px-8 py-6 max-w-7xl mx-auto space-y-8">
      <div>
        <h1 className="text-3xl font-semibold">Marketplace</h1>
        <p className="text-gray-500">
          Explora y compra productos listos para entrega
        </p>
      </div>

      <Filters
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
        filterType={filterType}
        setFilterType={setFilterType}
      />

      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {filtered.map((p) => (
          <ProductCard key={p.id} product={p} onBuy={() => handleBuy(p)} onViewReviews={() => handleViewReviews(p)} />
        ))}
      </div>

      {filtered.length === 0 && (
        <p className="text-center text-gray-500">
          No se encontraron productos
        </p>
      )}

      {/* Modal de parámetros */}
      {selectedProduct && (
        <BuyOrderModal
          product={selectedProduct}
          isOpen={showBuyModal}
          onClose={handleCloseBuyModal}
          attrValues={attrValues}
          errors={errors}
          loading={loading}
          quantity={quantity}
          onQuantityChange={setQuantity}
          onFieldChange={setField}
          onConfirm={handleBuyConfirm}
          initAttributes={initAttributes}
        />
      )}

      {/* Modal de confirmación */}
      {selectedProduct && (
        <ConfirmBuyModal
          productTitle={selectedProduct.title}
          quantity={quantity}
          totalAmount={(Number(selectedProduct.price || 0) * quantity) + Math.round(Number(selectedProduct.price || 0) * quantity * 0.19)}
          isOpen={showConfirmModal}
          onConfirm={handleFinalConfirm}
          onCancel={handleCloseConfirmModal}
          loading={loading}
        />
      )}

      {selectedReviewsProduct && (
        <ProductReviewsModal
          open={Boolean(selectedReviewsProduct)}
          onOpenChange={(nextOpen) => {
            if (!nextOpen) {
              setSelectedReviewsProduct(null);
            }
          }}
          productId={selectedReviewsProduct.id}
          productTitle={selectedReviewsProduct.title}
          summaryRating={selectedReviewsProduct.rating}
          summaryReviews={selectedReviewsProduct.reviews}
          allowReview={hasToken}
        />
      )}
    </div>
  );
};

'use client';

import { useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { MessageSquareText, RefreshCcw, Star } from 'lucide-react';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { interactionService, type ProductReview } from '@/services/interaction.service';

interface ProductCommentsSectionProps {
  productId: number;
  productTitle: string;
  summaryRating?: number;
  summaryReviews?: number;
  allowReview?: boolean;
}

function getRole() {
  if (typeof window !== 'undefined') {
    return localStorage.getItem('role');
  }
  return null;
}

function StarDisplay({ value }: { value: number }) {
  return (
    <div className="flex items-center gap-1">
      {Array.from({ length: 5 }).map((_, index) => {
        const filled = index < Math.round(value);
        return (
          <Star
            key={index}
            className={`w-5 h-5 ${filled ? 'fill-yellow-500 text-yellow-500' : 'text-muted-foreground/30'}`}
          />
        );
      })}
    </div>
  );
}

export function ProductCommentsSection({
  productId,
  productTitle,
  summaryRating = 0,
  summaryReviews = 0,
  allowReview = false,
}: ProductCommentsSectionProps) {
  const router = useRouter();
  const [reviews, setReviews] = useState<ProductReview[]>([]);
  const [loading, setLoading] = useState(true);
  const [reviewRating, setReviewRating] = useState(5);
  const [reviewComment, setReviewComment] = useState('');
  const [saving, setSaving] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [role, setRole] = useState<string | null>(null);

  const canReview = allowReview && role === 'cliente';

  useEffect(() => {
    setRole(getRole());
  }, []);

  const loadReviews = async () => {
    setLoading(true);
    try {
      const data = await interactionService.getProductReviews(productId);
      setReviews(data.items);
    } catch (error: any) {
      toast.error(error?.message || 'No se pudieron cargar los comentarios');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadReviews();
  }, [productId]);

  const averageRating = useMemo(() => {
    if (summaryReviews > 0) return summaryRating;
    if (reviews.length === 0) return 0;
    const total = reviews.reduce((acc, review) => acc + review.rating, 0);
    return total / reviews.length;
  }, [reviews, summaryRating, summaryReviews]);

  const handleSaveReview = async () => {
    setSaving(true);
    try {
      await interactionService.createReview(productId, reviewRating, reviewComment.trim());
      toast.success('Valoración guardada correctamente.');
      await loadReviews();
      setReviewComment('');
      setReviewRating(5);
      setShowConfirm(false);
    } catch (error: any) {
      if (error?.message === 'AUTH_REQUIRED') {
        localStorage.setItem('redirect_after_login', `/marketplace/${productId}?review=1`);
        router.push('/login');
        return;
      }
      toast.error(error?.message || 'No se pudo guardar la valoración');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div id="opiniones" className="mt-16 lg:mt-24 max-w-5xl mx-auto">
      <div className="flex items-center justify-between border-b border-border/50 pb-6 mb-8">
        <h2 className="text-2xl lg:text-3xl font-bold text-foreground">Opiniones del producto</h2>
        {reviews.length > 0 && (
          <div className="flex items-center gap-4">
            <div className="text-right">
              <div className="text-3xl font-bold text-foreground">{averageRating.toFixed(1)}</div>
              <div className="text-sm text-muted-foreground">{reviews.length} {reviews.length === 1 ? 'calificación' : 'calificaciones'}</div>
            </div>
            <StarDisplay value={averageRating} />
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        {/* Left column: Create Review Form */}
        <div className="lg:col-span-4 order-2 lg:order-1">
          <div className="sticky top-24 bg-muted/20 p-6 rounded-2xl border border-border/50 shadow-sm">
            <h3 className="font-semibold text-lg text-foreground mb-4">¿Qué te pareció el producto?</h3>
            {!canReview && (
              <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800 mb-6">
                Solo el comprador de un pedido entregado puede dejar una valoración. Inicia sesión si realizaste una compra.
              </div>
            )}
            
            <form
              className="space-y-6"
              onSubmit={(event) => {
                event.preventDefault();
                if (!canReview) {
                  localStorage.setItem('redirect_after_login', `/marketplace/${productId}?review=1`);
                  router.push('/login');
                  return;
                }
                setShowConfirm(true);
              }}
            >
              <div className="space-y-3">
                <label className="text-sm font-medium text-foreground">Tu calificación</label>
                <div className="flex flex-wrap items-center gap-2">
                  {Array.from({ length: 6 }).map((_, index) => {
                    const value = index;
                    const selected = reviewRating === value;
                    return (
                      <button
                        key={value}
                        type="button"
                        onClick={() => setReviewRating(value)}
                        className={`inline-flex h-10 min-w-10 items-center justify-center rounded-full border px-3 text-sm font-semibold transition-colors ${selected ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-background text-foreground hover:bg-muted'}`}
                      >
                        {value}
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-sm font-medium text-foreground">Cuéntanos más (opcional)</label>
                <textarea
                  value={reviewComment}
                  onChange={(event) => setReviewComment(event.target.value)}
                  placeholder="¿Qué te gustó más del producto? ¿Cómo fue tu experiencia?"
                  rows={4}
                  className="w-full rounded-xl border border-border bg-background px-4 py-3 text-sm outline-none transition-shadow focus:ring-2 focus:ring-primary/30"
                />
              </div>

              <Button type="submit" className="w-full gap-2 py-6 text-base" disabled={saving}>
                <Star className="h-5 w-5" />
                Guardar valoración
              </Button>
            </form>
          </div>
        </div>

        {/* Right column: Comments List */}
        <div className="lg:col-span-8 order-1 lg:order-2">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-semibold text-lg text-foreground">Comentarios más recientes</h3>
            <Button
              size="sm"
              variant="ghost"
              className="gap-2 text-muted-foreground hover:text-foreground"
              disabled={loading}
              onClick={async () => {
                await loadReviews();
                toast.success('Comentarios actualizados.');
              }}
            >
              <RefreshCcw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
              Actualizar
            </Button>
          </div>

          {loading ? (
            <div className="flex flex-col items-center justify-center py-20 text-muted-foreground space-y-4">
              <RefreshCcw className="w-8 h-8 animate-spin" />
              <p>Cargando opiniones...</p>
            </div>
          ) : reviews.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 rounded-2xl border border-dashed border-border/70 bg-muted/10 px-6 text-center">
              <div className="bg-background p-4 rounded-full shadow-sm mb-4">
                <MessageSquareText className="w-8 h-8 text-muted-foreground" />
              </div>
              <h3 className="font-semibold text-foreground text-lg mb-2">Sin opiniones aún</h3>
              <p className="text-sm text-muted-foreground max-w-sm">
                Sé el primero en dejar un comentario sobre este producto y ayuda a otros clientes a decidirse.
              </p>
            </div>
          ) : (
            <div className="space-y-6">
              {reviews.map((review) => (
                <article key={review.id} className="rounded-2xl border border-border/50 bg-background p-6 shadow-sm hover:shadow-md transition-shadow">
                  <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4 mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center text-primary font-bold">
                        {review.userName.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <div className="font-semibold text-foreground">{review.userName}</div>
                        <div className="text-xs text-muted-foreground mt-0.5">
                          {new Date(review.createdAt).toLocaleDateString('es-CO', {
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric',
                          })}
                        </div>
                      </div>
                    </div>
                    <StarDisplay value={review.rating} />
                  </div>
                  {review.comment ? (
                    <p className="text-base leading-relaxed text-muted-foreground whitespace-pre-wrap pl-13">
                      {review.comment}
                    </p>
                  ) : (
                    <p className="text-base italic text-muted-foreground/60 pl-13">
                      El usuario dejó una calificación sin comentario.
                    </p>
                  )}
                </article>
              ))}
            </div>
          )}
        </div>
      </div>

      <AlertDialog open={showConfirm} onOpenChange={setShowConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar valoración</AlertDialogTitle>
            <AlertDialogDescription>
              Vas a guardar una valoración de {reviewRating} estrellas para {productTitle}.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={saving}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={(event) => {
                event.preventDefault();
                handleSaveReview();
              }}
              disabled={saving}
            >
              {saving ? 'Guardando...' : 'Confirmar'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

'use client';
import { useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';
import {
    adminMarketplaceService,
    type MarketplaceSavePayload,
} from '@/services/admin-marketplace.service';
import { type MarketplaceProduct } from '@/types/marketplace';
import {
    type FilterType,
    type ProductFormData,
    type ProductFormSubmit,
} from '@/components/marketplace/types/marketplace.types';
import { uploadProductMedia } from '@/services/media/uploadProductMedia';

export function useAdminMarketplace() {
    const [products, setProducts] = useState<MarketplaceProduct[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [filterType, setFilterType] = useState<FilterType>('all');
    const [loading, setLoading] = useState(true);
    const [isProcessing, setIsProcessing] = useState(false);
    // Modales
    const [showModal, setShowModal] = useState(false);
    const [modalMode, setModalMode] = useState<'create' | 'edit'>('create');
    const [editingProduct, setEditingProduct] = useState<MarketplaceProduct | null>(null);
    const [deletingProduct, setDeletingProduct] = useState<MarketplaceProduct | null>(null);
    const [pendingSave, setPendingSave] = useState<ProductFormSubmit | null>(null);
    const [pendingVisibility, setPendingVisibility] = useState<MarketplaceProduct | null>(null);

    useEffect(() => {
        const loadProducts = async () => {
            try {
                const data = await adminMarketplaceService.getProducts(searchTerm || null);
                setProducts(data);
            } catch (error: any) {
                toast.error(error?.message || 'No se pudieron cargar los productos');
            } finally {
                setLoading(false);
            }
        };
        loadProducts();
    }, [searchTerm]);

    // ── Filtrado ──────────────────────────────────────────────────────────────
    const filtered = products.filter((p) => {
        const term = searchTerm.toLowerCase();
        const matchesSearch =
            p.name.toLowerCase().includes(term) ||
            p.description.toLowerCase().includes(term);
        const matchesType = filterType === 'all' || p.productType === filterType;
        return matchesSearch && matchesType;
    });

    // ── Estadísticas ──────────────────────────────────────────────────────────
    const totalActive = products.filter((p) => p.isPublic).length;
    const totalInactive = products.filter((p) => !p.isPublic).length;
    const outOfStock = products.filter((p) => !p.inStock).length;

    // ── Acciones CRUD ─────────────────────────────────────────────────────────
    const openCreate = () => {
        setEditingProduct(null);
        setModalMode('create');
        setShowModal(true);
    };

    const openEdit = (product: MarketplaceProduct) => {
        setEditingProduct(product);
        setModalMode('edit');
        setShowModal(true);
    };

    const handleSave = (data: ProductFormSubmit) => {
        setPendingSave(data);
    };

    const confirmSave = async () => {
        if (!pendingSave) return;
        setIsProcessing(true);
        const toastId = toast.loading(modalMode === 'create' ? 'Creando producto...' : 'Guardando cambios...');
        const price = Number(pendingSave.basePrice);
        const stock = Number(pendingSave.stock);
        const payload: MarketplaceSavePayload = {
            name: pendingSave.name.trim(),
            description: pendingSave.description.trim(),
            basePrice: price,
            productType: pendingSave.productType,
            productShape: pendingSave.productShape.trim(),
            stock,
            shapeAttributes: pendingSave.shapeAttributes,
        };

        try {
            let finalProduct: MarketplaceProduct;

            if (modalMode === 'create') {
                finalProduct = await adminMarketplaceService.createProduct(payload);
                toast.success('Producto agregado al marketplace.', { id: toastId });
            } else {
                if (!editingProduct) return;
                finalProduct = await adminMarketplaceService.updateProduct(editingProduct.id, payload);
                toast.success('Producto actualizado correctamente.', { id: toastId });
            }

            const mediaToUpload = pendingSave.mediaItems?.filter(m => m.file);
            if (mediaToUpload && mediaToUpload.length > 0 && finalProduct.companyId) {
                await uploadProductMedia(finalProduct.companyId, Number(finalProduct.id), mediaToUpload);
                const refreshedProducts = await adminMarketplaceService.getProducts(searchTerm || null);
                setProducts(refreshedProducts);
            } else {
                if (modalMode === 'create') {
                    setProducts((prev) => [finalProduct, ...prev]);
                } else {
                    setProducts((prev) =>
                        prev.map((p) => (p.id === finalProduct.id ? finalProduct : p)),
                    );
                }
            }

            setPendingSave(null);
            setShowModal(false);
        } catch (error: any) {
            toast.error(error?.message || 'No se pudo guardar el producto', { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    const toggleActive = (productId: string) => {
        const product = products.find((p) => p.id === productId);
        if (!product) return;
        setPendingVisibility(product);
    };

    const confirmToggleActive = async () => {
        if (!pendingVisibility) return;
        setIsProcessing(true);
        const toastId = toast.loading(pendingVisibility.isPublic ? 'Desactivando producto...' : 'Activando producto...');
        try {
            const updated = await adminMarketplaceService.setVisibility(
                pendingVisibility.id,
                !pendingVisibility.isPublic,
            );
            setProducts((prev) => prev.map((p) => (p.id === pendingVisibility.id ? updated : p)));
            toast.success(
                pendingVisibility.isPublic
                    ? `"${pendingVisibility.name}" desactivado del marketplace.`
                    : `"${pendingVisibility.name}" activado en el marketplace.`,
                { id: toastId }
            );
            setPendingVisibility(null);
        } catch (error: any) {
            toast.error(error?.message || 'No se pudo cambiar visibilidad', { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    const confirmDelete = async () => {
        if (!deletingProduct) return;
        setIsProcessing(true);
        const toastId = toast.loading('Eliminando producto...');
        try {
            await adminMarketplaceService.deleteProduct(deletingProduct.id);
            setProducts((prev) => prev.filter((p) => p.id !== deletingProduct.id));
            toast.success(`"${deletingProduct.name}" eliminado.`, { id: toastId });
            setDeletingProduct(null);
        } catch (error: any) {
            toast.error(error?.message || 'No se pudo eliminar el producto', { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };

    // Forma tipada para el modal de edición
    const editInitialData: ProductFormData | undefined = useMemo(
        () => editingProduct
            ? {
                name: editingProduct.name,
                description: editingProduct.description,
                basePrice: String(editingProduct.basePrice),
                productType: editingProduct.productType,
                productShape: editingProduct.productShape || '',
                stock: String(editingProduct.stock),
            }
            : undefined,
        [editingProduct]
    );

    const editInitialMediaItems = useMemo(
        () => {
            if (!editingProduct) return [];

            return (
                editingProduct.media?.map((m: any) => ({
                    id: m.id?.toString() || crypto.randomUUID(),
                    previewUrl: m.storage_path,
                    media_kind: m.media_kind,
                    media_role: m.media_role,
                })) || (editingProduct.imageUrl ? [{
                    id: crypto.randomUUID(),
                    previewUrl: editingProduct.imageUrl,
                    media_kind: 'image' as const,
                    media_role: 'main' as const,
                }] : [])
            );
        },
        [editingProduct]
    );

    const editInitialShapeAttributes = useMemo(
        () => {
            if (!editingProduct?.attributes?.length) return undefined;

            return editingProduct.attributes.reduce<Record<string, string>>((accumulator, attribute: any) => {
                if (attribute?.code) {
                    accumulator[attribute.code] = attribute.default_value ?? '';
                }
                return accumulator;
            }, {});
        },
        [editingProduct]
    );

    return {
        // Estado
        products,
        filtered,
        searchTerm,
        setSearchTerm,
        filterType,
        setFilterType,
        loading,
        isProcessing,
        // Estadísticas
        totalActive,
        totalInactive,
        outOfStock,
        // Modal crear/editar
        showModal,
        setShowModal,
        modalMode,
        editingProduct,
        editInitialData,
        editInitialMediaItems,
        editInitialShapeAttributes,
        openCreate,
        openEdit,
        handleSave,
        // Confirmación guardar
        pendingSave,
        setPendingSave,
        confirmSave,
        // Visibilidad
        pendingVisibility,
        setPendingVisibility,
        toggleActive,
        confirmToggleActive,
        // Eliminar
        deletingProduct,
        setDeletingProduct,
        confirmDelete,
    };
}

'use client';
import { useEffect, useMemo, useState } from 'react';
import { toast } from 'sonner';
import {
    funcionarioMarketplaceService,
    type MarketplaceSavePayload,
} from '@/services/funcionario-marketplace.service';
import { type MarketplaceProduct } from '@/types/marketplace';
import {
    type FilterType,
    type ProductFormData,
    type ProductFormSubmit,
} from '@/components/marketplace/types/marketplace.types';
import { uploadProductMedia } from '@/services/media/uploadProductMedia';

export function useMarketplace() {
    const [products, setProducts] = useState<MarketplaceProduct[]>([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [filterType, setFilterType] = useState<FilterType>('all');
    const [loading, setLoading] = useState(true);
    const [isProcessing, setIsProcessing] = useState(false);
    // Modales
    const [showModal, setShowModal] = useState(false);
    const [modalMode, setModalMode] = useState<'create' | 'edit'>('create');
    const [editingProduct, setEditingProduct] = useState<MarketplaceProduct | null>(null);
    const [deletingProduct, setDeletingProduct] = useState<MarketplaceProduct | null>(null);
    const [pendingSave, setPendingSave] = useState<ProductFormSubmit | null>(null);
    const [pendingVisibility, setPendingVisibility] = useState<MarketplaceProduct | null>(null);
    useEffect(() => {
        const loadProducts = async () => {
            try {
                const data = await funcionarioMarketplaceService.getProducts();
                setProducts(data);
            } catch (error: any) {
                toast.error(error?.message || 'No se pudieron cargar los productos');
            } finally {
                setLoading(false);
            }
        };
        loadProducts();
    }, []);
    // ── Filtrado ──────────────────────────────────────────────────────────────
    const filtered = products.filter((p) => {
        const term = searchTerm.toLowerCase();
        const matchesSearch =
            p.name.toLowerCase().includes(term) ||
            p.description.toLowerCase().includes(term);
        const matchesType = filterType === 'all' || p.productType === filterType;
        return matchesSearch && matchesType;
    });
    // ── Estadísticas ──────────────────────────────────────────────────────────
    const totalActive = products.filter((p) => p.isPublic).length;
    const totalInactive = products.filter((p) => !p.isPublic).length;
    const outOfStock = products.filter((p) => !p.inStock).length;
    // ── Acciones CRUD ─────────────────────────────────────────────────────────
    const openCreate = () => {
        setEditingProduct(null);
        setModalMode('create');
        setShowModal(true);
    };
    const openEdit = (product: MarketplaceProduct) => {
        setEditingProduct(product);
        setModalMode('edit');
        setShowModal(true);
    };
    const handleSave = (data: ProductFormSubmit) => {
        setPendingSave(data);
    };
    const confirmSave = async () => {
        if (!pendingSave) return;
        setIsProcessing(true);
        const toastId = toast.loading(modalMode === 'create' ? 'Creando producto...' : 'Guardando cambios...');
        const price = Number(pendingSave.basePrice);
        const stock = Number(pendingSave.stock);
        const payload: MarketplaceSavePayload = {
            name: pendingSave.name.trim(),
            description: pendingSave.description.trim(),
            basePrice: price,
            productType: pendingSave.productType,
            productShape: pendingSave.productShape.trim(),
            stock,
            shapeAttributes: pendingSave.shapeAttributes,
        };
        try {
            let finalProduct: MarketplaceProduct;
            
            if (modalMode === 'create') {
                finalProduct = await funcionarioMarketplaceService.createProduct(payload);
                toast.success('Producto agregado al marketplace.', { id: toastId });
            } else {
                if (!editingProduct) return;
                finalProduct = await funcionarioMarketplaceService.updateProduct(editingProduct.id, payload);
                toast.success('Producto actualizado correctamente.', { id: toastId });
            }

            const mediaToUpload = pendingSave.mediaItems?.filter(m => m.file);
            if (mediaToUpload && mediaToUpload.length > 0 && finalProduct.companyId) {
                await uploadProductMedia(finalProduct.companyId, Number(finalProduct.id), mediaToUpload);
                const refreshedProducts = await funcionarioMarketplaceService.getProducts();
                setProducts(refreshedProducts);
            } else {
                if (modalMode === 'create') {
                    setProducts((prev) => [finalProduct, ...prev]);
                } else {
                    setProducts((prev) =>
                        prev.map((p) => (p.id === finalProduct.id ? finalProduct : p)),
                    );
                }
            }

            setPendingSave(null);
            setShowModal(false);
        } catch (error: any) {
            toast.error(error?.message || 'No se pudo guardar el producto', { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };
    const toggleActive = (productId: string) => {
        const product = products.find((p) => p.id === productId);
        if (!product) return;
        setPendingVisibility(product);
    };
    const confirmToggleActive = async () => {
        if (!pendingVisibility) return;
        setIsProcessing(true);
        const toastId = toast.loading(pendingVisibility.isPublic ? 'Desactivando producto...' : 'Activando producto...');
        try {
            const updated = await funcionarioMarketplaceService.setVisibility(
                pendingVisibility.id,
                !pendingVisibility.isPublic,
            );
            setProducts((prev) => prev.map((p) => (p.id === pendingVisibility.id ? updated : p)));
            toast.success(
                pendingVisibility.isPublic
                    ? `"${pendingVisibility.name}" desactivado del marketplace.`
                    : `"${pendingVisibility.name}" activado en el marketplace.`,
                { id: toastId }
            );
            setPendingVisibility(null);
        } catch (error: any) {
            toast.error(error?.message || 'No se pudo cambiar visibilidad', { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };
    const confirmDelete = async () => {
        if (!deletingProduct) return;
        setIsProcessing(true);
        const toastId = toast.loading('Eliminando producto...');
        try {
            await funcionarioMarketplaceService.deleteProduct(deletingProduct.id);
            setProducts((prev) => prev.filter((p) => p.id !== deletingProduct.id));
            toast.success(`"${deletingProduct.name}" eliminado.`, { id: toastId });
            setDeletingProduct(null);
        } catch (error: any) {
            toast.error(error?.message || 'No se pudo eliminar el producto', { id: toastId });
        } finally {
            setIsProcessing(false);
        }
    };
    // Forma tipada para el modal de edición
    const editInitialData: ProductFormData | undefined = useMemo(
        () => editingProduct
            ? {
                name: editingProduct.name,
                description: editingProduct.description,
                basePrice: String(editingProduct.basePrice),
                productType: editingProduct.productType,
                productShape: editingProduct.productShape || '',
                stock: String(editingProduct.stock),
            }
            : undefined,
        [editingProduct]
    );

    const editInitialMediaItems = useMemo(
        () => {
            if (!editingProduct) return [];

            return (
                editingProduct.media?.map((m: any) => ({
                    id: m.id?.toString() || crypto.randomUUID(),
                    previewUrl: m.storage_path,
                    media_kind: m.media_kind,
                    media_role: m.media_role,
                })) || (editingProduct.imageUrl ? [{
                    id: crypto.randomUUID(),
                    previewUrl: editingProduct.imageUrl,
                    media_kind: 'image' as const,
                    media_role: 'main' as const,
                }] : [])
            );
        },
        [editingProduct]
    );

    const editInitialShapeAttributes = useMemo(
        () => {
            if (!editingProduct?.attributes?.length) return undefined;

            return editingProduct.attributes.reduce<Record<string, string>>((accumulator, attribute: any) => {
                if (attribute?.code) {
                    accumulator[attribute.code] = attribute.default_value ?? '';
                }
                return accumulator;
            }, {});
        },
        [editingProduct]
    );
    return {
        // Estado
        products,
        filtered,
        searchTerm,
        setSearchTerm,
        filterType,
        setFilterType,
        loading,
        isProcessing,
        // Estadísticas
        totalActive,
        totalInactive,
        outOfStock,
        // Modal crear/editar
        showModal,
        setShowModal,
        modalMode,
        editingProduct,
        editInitialData,
        editInitialMediaItems,
        editInitialShapeAttributes,
        openCreate,
        openEdit,
        handleSave,
        // Confirmación guardar
        pendingSave,
        setPendingSave,
        confirmSave,
        // Visibilidad
        pendingVisibility,
        setPendingVisibility,
        toggleActive,
        confirmToggleActive,
        // Eliminar
        deletingProduct,
        setDeletingProduct,
        confirmDelete,
    };
}

import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { toast } from 'sonner';
import { paymentService } from '@/services/payment.service';
import { ProductAttribute } from '@/types/product';
import { audioService } from '@/services/audio.service';

export function useMarketplaceBuy() {
  const router = useRouter();
  const [attrValues, setAttrValues] = useState<Record<string, string>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [quantity, setQuantity] = useState(1);

  const initAttributes = (attributes: ProductAttribute[]) => {
    setAttrValues((prev) => {
      const next = { ...prev };

      attributes.forEach((attribute) => {
        if (next[attribute.code] && next[attribute.code].trim() !== '') {
          return;
        }

        if (attribute.default_value && attribute.default_value.trim() !== '') {
          next[attribute.code] = attribute.default_value.trim();
          return;
        }

        if (attribute.input_type === 'color') {
          next[attribute.code] = '#000000';
          return;
        }

        next[attribute.code] = (attribute.placeholder || '').trim();
      });

      return next;
    });
  };

  const validateForm = (attributes: ProductAttribute[], stock?: number): boolean => {
    const newErrors: Record<string, string> = {};

    if (!Number.isInteger(quantity) || quantity < 1 || quantity > 10) {
      newErrors.quantity = 'La cantidad debe estar entre 1 y 10.';
    } else if (typeof stock === 'number' && quantity > stock) {
      newErrors.quantity = 'La cantidad no puede superar el stock disponible.';
    }

    attributes.forEach(attr => {
      const val = attrValues[attr.code] || attr.default_value || '';
      if (attr.required && (!val || val.trim() === '')) {
        newErrors[attr.code] = `El campo ${attr.label} es obligatorio.`;
      } else if (attr.input_type === 'number' && val) {
        if (isNaN(Number(val)) || Number(val) <= 0) {
          newErrors[attr.code] = `El campo ${attr.label} debe ser mayor a 0.`;
        }
      }
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const createOrder = async (
    productId: number,
    productTitle: string,
    attributes: ProductAttribute[],
    stock?: number
  ): Promise<boolean> => {
    if (!validateForm(attributes, stock)) {
      return false;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('token');

      if (!token) {
        localStorage.setItem('redirect_after_login', '/marketplace');
        toast.error('Debes iniciar sesión');
        router.push('/login');
        return false;
      }

      // Format custom_attributes payload
      const customAttributes: Record<string, string> = {};
      attributes.forEach(attr => {
        const value = (attrValues[attr.code] || attr.default_value || '').trim();
        if (value !== '') {
          customAttributes[attr.code] = value;
        }
      });

      const result = await paymentService.createMarketplaceOrder({
        product_id: productId,
        quantity,
        attributes: customAttributes,
      });

      if (!result.payment_url) {
        throw new Error('No se pudo iniciar el pago con PayU');
      }

      if (result.payment_action_url && result.payment_payload) {
        sessionStorage.setItem(
          `payu_payload_${result.order_id}`,
          JSON.stringify({
            actionUrl: result.payment_action_url,
            payload: result.payment_payload,
          })
        );
      }

      audioService.playSuccessOrder();
      toast.success(`Pedido de "${productTitle}" creado. Continúa al checkout seguro.`);
      resetForm();

      router.push(`/pagos/checkout?orderId=${result.order_id}`);
      
      return true;
    } catch (error: any) {
      const message = error?.message || 'Error al crear la orden';

      if (message === 'AUTH_REQUIRED' || message === 'SESSION_EXPIRED') {
        localStorage.setItem('redirect_after_login', '/marketplace');
        toast.error('Tu sesión expiró. Inicia sesión nuevamente.');
        router.push('/login');
        return false;
      }

      // Log detailed error for debugging
      console.error('Error creating marketplace order:', error);

      // Show user-friendly error message
      const userMessage = message.includes('body.')
        ? `Datos inválidos: ${message.split('; ').join(', ')}`
        : message;

      toast.error(userMessage);
      return false;
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setAttrValues({});
    setErrors({});
    setQuantity(1);
  };

  const setField = (code: string, value: string) => {
    setAttrValues((prev) => ({ ...prev, [code]: value }));
    if (errors[code]) {
      setErrors((prev) => {
        const next = { ...prev };
        delete next[code];
        return next;
      });
    }
  };

  const hasErrors = (): boolean => {
    return Object.values(errors).some(error => error !== '');
  };

  return {
    attrValues,
    errors,
    loading,
    quantity,
    setQuantity,
    initAttributes,
    setField,
    validateForm,
    createOrder,
    resetForm,
    hasErrors,
  };
}

'use client';

import { X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Product, ProductAttribute } from '@/types/product';
import { useEffect, useMemo } from 'react';

interface BuyOrderModalProps {
  product: Product;
  isOpen: boolean;
  onClose: () => void;
  attrValues: Record<string, string>;
  errors: Record<string, string>;
  loading: boolean;
  quantity: number;
  onQuantityChange: (value: number) => void;
  onFieldChange: (code: string, value: string) => void;
  onConfirm: () => void;
  initAttributes: (attributes: ProductAttribute[]) => void;
}

export function BuyOrderModal({
  product,
  isOpen,
  onClose,
  attrValues,
  errors,
  loading,
  quantity,
  onQuantityChange,
  onFieldChange,
  onConfirm,
  initAttributes,
}: BuyOrderModalProps) {
  useEffect(() => {
    if (isOpen && product.attributes && product.attributes.length > 0) {
      initAttributes(product.attributes);
    }
  }, [isOpen, product.attributes]);

  const visibleAttributes = useMemo(
    () => (product.attributes || [])
      .filter((attribute) => attribute.code !== 'color' && attribute.input_type !== 'color')
      .sort((a, b) => a.sort_order - b.sort_order),
    [product.attributes],
  );

  const getAttributeDisplayValue = (attribute: ProductAttribute): string => {
    const persistedValue = (attribute.default_value || '').trim();
    if (persistedValue) return persistedValue;
    if (attribute.placeholder && attribute.placeholder.trim()) return attribute.placeholder.trim();
    if (attribute.input_type === 'color') return '#000000';
    return 'No definido';
  };

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onConfirm();
  };

  const subtotal = Number(product.price || 0) * quantity;
  const tax = Math.round(subtotal * 0.19 * 100) / 100;
  const total = subtotal + tax;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="bg-background text-foreground border border-border rounded-xl shadow-xl w-full max-w-md max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border">
          <div>
            <h2 className="text-lg font-semibold">Resumen de compra</h2>
            <p className="text-sm text-muted-foreground mt-1">{product.title}</p>
            <p className="text-xs text-muted-foreground mt-1">Stock disponible: {product.stock}</p>
          </div>
          <button
            onClick={onClose}
            className="p-1 rounded-md hover:bg-muted transition-colors"
            disabled={loading}
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="px-6 py-5 space-y-4">
          <div className="space-y-4">
            {visibleAttributes.length > 0 ? (
              <div className="space-y-3 rounded-2xl border border-border bg-muted/20 p-4">
                {visibleAttributes.map((attribute) => (
                  <div
                    key={attribute.code}
                    className="flex items-start justify-between gap-4 border-b border-border/60 pb-3 last:border-b-0 last:pb-0"
                  >
                    <div>
                      <p className="text-sm font-medium text-foreground">
                        {attribute.label}{attribute.required ? '*' : ''}
                      </p>
                    </div>
                    <span className="text-sm font-medium text-foreground text-right">
                      {getAttributeDisplayValue(attribute)}
                    </span>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-muted-foreground italic py-2">
                Este producto no tiene atributos configurados.
              </p>
            )}

            <div className="grid grid-cols-2 gap-3 items-end">
              <div>
                <label className="block text-sm font-medium text-foreground mb-1">Cantidad</label>
                <input
                  type="number"
                  min={1}
                  max={10}
                  value={quantity}
                  onChange={(event) => onQuantityChange(Number(event.target.value) || 1)}
                  className="w-full border border-border bg-background rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-accent focus:border-transparent transition-shadow"
                  disabled={loading}
                />
                {errors.quantity && (
                  <p className="text-xs text-red-500 mt-1">{errors.quantity}</p>
                )}
              </div>
              <div className="text-right text-xs text-muted-foreground">
                Máximo 10 unidades por pedido
              </div>
            </div>

            <div className="rounded-lg border border-border bg-muted/20 p-4 text-sm space-y-1">
              <div className="flex items-center justify-between">
                <span>Subtotal</span>
                <span>${subtotal.toLocaleString('es-CO')}</span>
              </div>
              <div className="flex items-center justify-between">
                <span>IVA</span>
                <span>${tax.toLocaleString('es-CO')}</span>
              </div>
              <div className="flex items-center justify-between font-semibold text-foreground">
                <span>Total</span>
                <span>${total.toLocaleString('es-CO')}</span>
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3 pt-4 border-t border-border">
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={loading}
            >
              Cancelar
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? 'Procesando...' : 'Continuar'}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

