'use client';

import { useEffect, useMemo, useState } from 'react';
import { MessageSquareText, RefreshCcw, Star } from 'lucide-react';
import { toast } from 'sonner';

import { Button } from '@/components/ui/button';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { ScrollArea } from '@/components/ui/scroll-area';
import { interactionService, type ProductReview } from '@/services/interaction.service';

type Mode = 'comments' | 'review';

interface ProductReviewsModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  productId: number;
  productTitle: string;
  summaryRating?: number;
  summaryReviews?: number;
  allowReview?: boolean;
  initialMode?: Mode;
}

// Componente arreglado: usa spans en lugar de divs para evitar error de hidratación
function StarDisplay({ value }: { value: number }) {
  return (
    <span className="inline-flex items-center gap-0.5">
      {Array.from({ length: 5 }).map((_, index) => {
        const filled = index < Math.round(value);
        return (
          <span key={index} className="inline-flex">
            <Star
              className={`w-4 h-4 ${filled ? 'fill-yellow-500 text-yellow-500' : 'text-muted-foreground/30'}`}
            />
          </span>
        );
      })}
    </span>
  );
}

export function ProductReviewsModal({
  open,
  onOpenChange,
  productId,
  productTitle,
  summaryRating = 0,
  summaryReviews = 0,
  allowReview = false,
  initialMode = 'comments',
}: ProductReviewsModalProps) {
  const [mode, setMode] = useState<Mode>(initialMode);
  const [reviews, setReviews] = useState<ProductReview[]>([]);
  const [loading, setLoading] = useState(false);
  const [reviewRating, setReviewRating] = useState<number | null>(null);
  const [reviewComment, setReviewComment] = useState('');
  const [saving, setSaving] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [ratingError, setRatingError] = useState<string | null>(null);

  const canReview = allowReview;

  useEffect(() => {
    if (open) {
      setMode(initialMode);
    }
  }, [initialMode, open]);

  useEffect(() => {
    if (!open) return;

    const loadReviews = async () => {
      setLoading(true);
      try {
        const data = await interactionService.getProductReviews(productId);
        setReviews(data.items);
      } catch (error: any) {
        toast.error(error?.message || 'No se pudieron cargar los comentarios');
      } finally {
        setLoading(false);
      }
    };

    loadReviews();
  }, [open, productId]);

  const averageRating = useMemo(() => {
    if (reviews.length === 0) return 0;
    const total = reviews.reduce((acc, review) => acc + review.rating, 0);
    return total / reviews.length;
  }, [reviews]);

  const visibleComments = useMemo(
    () => reviews.filter((review) => Boolean(review.comment && review.comment.trim().length > 0)),
    [reviews],
  );

  const handleSaveReview = async () => {
    if (reviewRating === null) {
      setRatingError('La puntuación es obligatoria.');
      toast.error('La puntuación es obligatoria.');
      return;
    }

    setSaving(true);
    try {
      await interactionService.createReview(productId, reviewRating, reviewComment.trim());
      toast.success('Valoración guardada correctamente.');
      const refreshed = await interactionService.getProductReviews(productId);
      setReviews(refreshed.items);
      setReviewComment('');
      setReviewRating(5);
      setRatingError(null);
      setShowConfirm(false);
      onOpenChange(false);
    } catch (error: any) {
      toast.error(error?.message || 'No se pudo guardar la valoración');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[94vh] overflow-hidden p-0 gap-0">
        <DialogHeader className="border-b border-border/60 px-6 py-5 text-left">
          <div className="flex items-start justify-between gap-4">
            <div>
              <DialogTitle className="text-xl">{productTitle}</DialogTitle>

              <DialogDescription className="mt-1">
                {summaryReviews > 0
                  ? 'Resumen de valoraciones del producto.'
                  : 'Todavía no hay valoraciones registradas.'}
              </DialogDescription>

              {summaryReviews > 0 && (
                <div className="mt-2 inline-flex items-center gap-2 text-sm text-muted-foreground">
                  <span className="font-semibold text-foreground">
                    {averageRating.toFixed(1)}
                  </span>

                  <StarDisplay value={averageRating} />

                  <span>({summaryReviews} valoraciones)</span>
                </div>
              )}
            </div>
          </div>
        </DialogHeader>

        {mode === 'comments' ? (
          <div className="flex flex-col max-h-[calc(94vh-88px)]">
            <div className="border-b border-border/60 px-6 py-3 flex items-center justify-between">
              <h3 className="font-semibold text-sm text-foreground">Comentarios ({visibleComments.length})</h3>
              <Button
                size="sm"
                variant="outline"
                className="gap-2 h-8"
                disabled={loading}
                onClick={async () => {
                  setLoading(true);
                  try {
                    const data = await interactionService.getProductReviews(productId);
                    setReviews(data.items);
                    toast.success('Comentarios actualizados.');
                  } catch (error: any) {
                    toast.error(error?.message || 'No se pudieron actualizar los comentarios');
                  } finally {
                    setLoading(false);
                  }
                }}
              >
                <RefreshCcw className="h-3 w-3" />
                Actualizar
              </Button>
            </div>
            <ScrollArea className="flex-1 px-6 py-5">
              {loading ? (
                <div className="flex h-full min-h-[220px] items-center justify-center text-sm text-muted-foreground">
                  Cargando comentarios...
                </div>
              ) : visibleComments.length === 0 ? (
                <div className="flex min-h-[220px] flex-col items-center justify-center rounded-2xl border border-dashed border-border/70 bg-muted/20 px-6 text-center">
                  <MessageSquareText className="mb-3 w-8 h-8 text-muted-foreground" />
                  <h3 className="font-semibold text-foreground">Sin comentarios aún</h3>
                  <p className="mt-1 text-sm text-muted-foreground max-w-sm">
                    Cuando un cliente deje un comentario, aparecerá aquí.
                  </p>
                </div>
              ) : (
                <div className="space-y-4">
                  {visibleComments.map((review) => (
                    <article key={review.id} className="rounded-2xl border border-border/70 bg-background p-4 shadow-sm">
                      <div className="flex items-start justify-between gap-3 mb-3">
                        <div>
                          <div className="font-medium text-foreground">{review.userName}</div>
                          <div className="mt-1 text-xs text-muted-foreground">
                            {new Date(review.createdAt).toLocaleDateString('es-CO', {
                              year: 'numeric',
                              month: 'short',
                              day: 'numeric',
                            })}
                          </div>
                        </div>
                        <StarDisplay value={review.rating} />
                      </div>
                      {review.comment ? (
                        <p className="text-sm leading-relaxed text-muted-foreground whitespace-pre-wrap">
                          {review.comment}
                        </p>
                      ) : (
                        <p className="text-sm italic text-muted-foreground/80">
                          Sin comentario adicional.
                        </p>
                      )}
                    </article>
                  ))}
                </div>
              )}
            </ScrollArea>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto px-6 py-5 pb-8">
            <form
              className="space-y-4"
              onSubmit={(event) => {
                event.preventDefault();
                if (!canReview) {
                  toast.error('Solo el comprador de un pedido entregado puede dejar una valoración.');
                  return;
                }
                if (reviewRating === null) {
                  toast.error('La puntuación es obligatoria.');
                  return;
                }
                setShowConfirm(true);
              }}
            >
              <div className="rounded-2xl border border-border/70 bg-background p-6 shadow-sm space-y-5">
                <div>
                  <h3 className="font-semibold text-foreground">Tu valoración</h3>
                  <p className="mt-1 text-sm text-muted-foreground">
                    Puntúa de 0 a 5 estrellas y deja un comentario si quieres.
                  </p>
                </div>

                <div className="space-y-3">
                  <label className="text-sm font-medium text-foreground">Puntuación</label>
                  <div className="flex flex-wrap items-center gap-2">
                    {Array.from({ length: 6 }).map((_, index) => {
                      const value = index;
                      const selected = reviewRating === value;
                      return (
                        <button
                          key={value}
                          type="button"
                          onClick={() => {
                            setReviewRating(value);
                            setRatingError(null);
                          }}
                          className={`inline-flex h-10 min-w-10 items-center justify-center rounded-full border px-3 text-sm font-semibold transition-colors ${selected ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-background text-foreground hover:bg-muted'}`}
                        >
                          {value}
                        </button>
                      );
                    })}
                  </div>
                  {reviewRating === null && (
                    <p className="text-sm font-medium text-red-600">
                      Debes seleccionar una puntuación para guardar la valoración.
                    </p>
                  )}
                  {ratingError && <p className="text-sm font-medium text-red-600">{ratingError}</p>}
                </div>

                <div className="space-y-3">
                  <label className="text-sm font-medium text-foreground">Comentario (opcional)</label>
                  <textarea
                    value={reviewComment}
                    onChange={(event) => setReviewComment(event.target.value)}
                    placeholder="Cuéntanos qué te pareció el producto..."
                    rows={8}
                    className="w-full rounded-xl border border-border bg-background px-4 py-3 text-sm outline-none transition-shadow focus:ring-2 focus:ring-primary/30"
                  />
                </div>
              </div>

              <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end pt-4">
                <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                  Cancelar
                </Button>
                <Button type="submit" className="gap-2" disabled={saving}>
                  <Star className="h-4 w-4" />
                  {saving ? 'Guardando...' : 'Guardar valoración'}
                </Button>
              </div>
            </form>
          </div>
        )}
      </DialogContent>

      <AlertDialog open={showConfirm} onOpenChange={setShowConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar valoración</AlertDialogTitle>
            <AlertDialogDescription>
              Vas a guardar una valoración de {reviewRating ?? 0} estrellas para {productTitle}. Puedes editarla más adelante si deseas.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={saving}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={(event) => {
                event.preventDefault();
                handleSaveReview();
              }}
              disabled={saving}
            >
              {saving ? 'Guardando...' : 'Confirmar'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Dialog>
  );
}

'use client';

import { useEffect, useState } from 'react';
import Image from 'next/image';
import { Dialog, DialogContent, DialogDescription, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import { funcionarioOrderService, type OrderDetail } from '@/services/funcionario-order.service';
import { ProductService } from '@/services/product.service';
import { getImageUrl } from '@/lib/supabase/getImageUrl';
import { getStatusColor } from '@/lib/utils/statusColors';
import { ChevronLeft, ChevronRight } from 'lucide-react';

type ResolvedMedia = {
  bucket: string;
  path: string;
  mediaKind?: string | null;
  mediaRole?: string | null;
  mimeType?: string | null;
  sortOrder?: number | null;
  url: string | null;
};

interface OrderDetailsModalProps {
  orderId: string | number;
  isOpen: boolean;
  onClose: () => void;
}

export function OrderDetailsModal({ orderId, isOpen, onClose }: OrderDetailsModalProps) {
  const [order, setOrder] = useState<OrderDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [resolvedImageUrl, setResolvedImageUrl] = useState<string | null>(null);
  const [resolvedMedia, setResolvedMedia] = useState<ResolvedMedia[]>([]);
  const [fallbackMedia, setFallbackMedia] = useState<ResolvedMedia[]>([]);
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0);

  useEffect(() => {
    if (!isOpen) return;

    let cancelled = false;

    const loadOrder = async () => {
      setLoading(true);
      setError(null);
      setResolvedImageUrl(null);
      setResolvedMedia([]);
      setFallbackMedia([]);

      try {
        const data = await funcionarioOrderService.getOrderDetail(orderId);

        if (!cancelled) {
          setOrder(data);
        }
      } catch (err) {
        if (!cancelled) {
          setError((err as { message?: string })?.message || 'Error al cargar los detalles');
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    void loadOrder();

    return () => {
      cancelled = true;
    };
  }, [isOpen, orderId]);

  useEffect(() => {
    if (!order || !isOpen) return;

    let cancelled = false;

    const sourceMedia: ResolvedMedia[] =
      order.media && order.media.length > 0
        ? order.media.map((media) => ({ ...media, url: null }))
        : order.image?.bucket && order.image?.path
          ? [{ bucket: order.image.bucket, path: order.image.path, url: null }]
          : [];

    const loadFallbackMedia = async () => {
      if (sourceMedia.length > 1 || !(order as any).productId) return;

      try {
        const product = await ProductService.getProductById(String((order as any).productId));
        const productMedia = (product.media || []).map((media) => ({
          bucket: media.bucket_name || 'product-catalog',
          path: media.storage_path,
          mediaKind: media.media_kind,
          mediaRole: media.media_role,
          mimeType: media.mime_type,
          sortOrder: media.sort_order,
          url: null,
        }));

        if (!cancelled && productMedia.length > 1) {
          setFallbackMedia(productMedia);
        }
      } catch {
        if (!cancelled) {
          setFallbackMedia([]);
        }
      }
    };

    void loadFallbackMedia();

    const resolveMedia = async () => {
      if (order.imageUrl) {
        setResolvedImageUrl(order.imageUrl);
      } else if (order.image?.bucket && order.image?.path) {
        try {
          const url = await getImageUrl(order.image.bucket, order.image.path);
          if (!cancelled) setResolvedImageUrl(url || null);
        } catch {
          if (!cancelled) setResolvedImageUrl(null);
        }
      } else {
        setResolvedImageUrl(null);
      }

      const resolved = await Promise.all(
        sourceMedia.map(async (media) => {
          try {
            const url = await getImageUrl(media.bucket, media.path);
            return { ...media, url: url || null };
          } catch {
            return { ...media, url: null };
          }
        }),
      );

      if (!cancelled) {
        setResolvedMedia(resolved);
      }
    };

    void resolveMedia();

    return () => {
      cancelled = true;
    };
  }, [order, isOpen]);

  const displayMedia = resolvedMedia.length > 1 ? resolvedMedia : fallbackMedia;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-card text-foreground border-border">
        {/* Accesibilidad: Radix requiere título y descripción siempre presentes */}
        <DialogTitle className="sr-only">
          {order ? `Detalle del pedido ${order.title}` : 'Detalle del pedido'}
        </DialogTitle>
        <DialogDescription className="sr-only">
          Modal con información detallada del pedido, estado, fechas, producto y parámetros.
        </DialogDescription>

        {loading ? (
          <div className="space-y-6">
            <Skeleton className="h-8 w-3/4" />
            <Skeleton className="h-64 w-full rounded-lg" />
            <div className="space-y-4">
              {Array.from({ length: 4 }).map((_, i) => (
                <Skeleton key={i} className="h-4 w-full" />
              ))}
            </div>
          </div>
        ) : error ? (
          <div className="py-8 text-center text-red-600">{error}</div>
        ) : order ? (
          <div className="space-y-6">
            {/* Header */}
            <div>
              <h2 className="text-2xl font-bold">{order.title}</h2>
              <p className="text-sm text-muted-foreground">ID: {order.id}</p>
            </div>

            {/* Imagen */}
            {(resolvedMedia.length > 0 || resolvedImageUrl) && (
              <div className="space-y-3">
                <div className="relative w-full aspect-video bg-muted rounded-lg overflow-hidden">
                  {displayMedia.length > 0 && displayMedia[currentMediaIndex]?.url ? (
                    <>
                      {displayMedia[currentMediaIndex].mediaKind === 'video' || (displayMedia[currentMediaIndex].mimeType || '').startsWith('video/') ? (
                        <video
                          src={displayMedia[currentMediaIndex].url}
                          controls
                          className="h-full w-full object-cover"
                        />
                      ) : (
                        <Image
                          src={displayMedia[currentMediaIndex].url}
                          alt={order.title}
                          fill
                          unoptimized
                          className="object-cover"
                          priority
                        />
                      )}
                    </>
                  ) : resolvedImageUrl ? (
                    <Image
                      src={resolvedImageUrl}
                      alt={order.title}
                      fill
                      unoptimized
                      className="object-cover"
                      priority
                    />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center text-sm text-muted-foreground">
                      Sin vista previa
                    </div>
                  )}
                  
                  {displayMedia.length > 1 && (
                    <>
                      <Button
                        size="sm"
                        variant="secondary"
                        className="absolute left-3 top-1/2 -translate-y-1/2 rounded-full w-10 h-10 p-0 gap-0"
                        onClick={() => setCurrentMediaIndex((prev) => (prev - 1 + displayMedia.length) % displayMedia.length)}
                      >
                        <ChevronLeft className="w-4 h-4" />
                      </Button>
                      
                      <Button
                        size="sm"
                        variant="secondary"
                        className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full w-10 h-10 p-0 gap-0"
                        onClick={() => setCurrentMediaIndex((prev) => (prev + 1) % displayMedia.length)}
                      >
                        <ChevronRight className="w-4 h-4" />
                      </Button>
                      
                      <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex items-center gap-2 rounded-full bg-black/50 px-3 py-1">
                        <span className="text-xs text-white font-medium">
                          {currentMediaIndex + 1} / {displayMedia.length}
                        </span>
                      </div>
                    </>
                  )}
                </div>

                {displayMedia.length > 1 && (
                  <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4">
                    {displayMedia.map((media, index) => (
                      <button
                        key={`${media.bucket}/${media.path}-${index}`}
                        onClick={() => setCurrentMediaIndex(index)}
                        className={`relative aspect-square overflow-hidden rounded-lg border-2 transition-colors ${
                          currentMediaIndex === index ? 'border-primary' : 'border-border/60'
                        } bg-muted/30`}
                      >
                        {media.url ? (
                          media.mediaKind === 'video' || (media.mimeType || '').startsWith('video/') ? (
                            <>
                              <video src={media.url} className="h-full w-full object-cover" />
                              <div className="absolute inset-0 flex items-center justify-center bg-black/30">
                                <div className="w-6 h-6 rounded-full bg-white flex items-center justify-center">
                                  <div className="w-0 h-0 border-l-3 border-l-white border-t-2 border-t-transparent border-b-2 border-b-transparent ml-1" />
                                </div>
                              </div>
                            </>
                          ) : (
                            <Image
                              src={media.url}
                              alt={`${order.title} thumbnail ${index + 1}`}
                              fill
                              unoptimized
                              className="object-cover"
                            />
                          )
                        ) : (
                          <div className="flex h-full w-full items-center justify-center text-[10px] uppercase tracking-[0.15em] text-muted-foreground">
                            Sin vista
                          </div>
                        )}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Estado y Precio */}
            <div className="grid grid-cols-2 gap-4">
              <Card className="p-4">
                <p className="text-sm text-muted-foreground mb-2">Estado</p>
                <span
                  className={`inline-flex items-center px-3 py-1 text-sm rounded-full font-medium ${getStatusColor(
                    order.status,
                  )}`}
                >
                  {order.status}
                </span>
              </Card>
              <Card className="p-4">
                <p className="text-sm text-muted-foreground mb-2">Precio</p>
                <p className="text-2xl font-bold text-primary">${order.price.toLocaleString()}</p>
              </Card>
            </div>

            {/* Fechas */}
            <Card className="p-4 space-y-3">
              <h3 className="font-semibold text-sm">Fechas</h3>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-xs text-muted-foreground">Creado</p>
                  <p className="text-sm font-medium">{new Date(order.createdAt).toLocaleDateString()}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground">Entrega</p>
                  <p className="text-sm font-medium">{new Date(order.deliveryDate).toLocaleDateString()}</p>
                </div>
              </div>
            </Card>

            {/* Información del Producto */}
            <Card className="p-4 space-y-3">
              <h3 className="font-semibold text-sm">Información del Producto</h3>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-xs text-muted-foreground">Tipo</p>
                  <p className="text-sm font-medium capitalize">{order.productType || 'N/A'}</p>
                </div>
                <div>
                  <p className="text-xs text-muted-foreground">Cantidad</p>
                  <p className="text-sm font-medium">{order.quantity}</p>
                </div>
              </div>
            </Card>

            {/* Parámetros del Pedido */}
            {order.attributes && order.attributes.length > 0 && (
              <Card className="p-4 space-y-3">
                <h3 className="font-semibold text-sm">Parámetros del Pedido</h3>
                <div className="grid grid-cols-2 gap-4">
                  {order.attributes.map(attr => (
                    <div key={attr.code}>
                      <p className="text-xs text-muted-foreground">{attr.label}</p>
                      <p className="text-sm font-medium capitalize">{attr.value}</p>
                    </div>
                  ))}
                </div>
              </Card>
            )}

            {/* Cliente (solo para funcionario) */}
            {order.clientName && (
              <Card className="p-4">
                <p className="text-xs text-muted-foreground mb-2">Cliente</p>
                <p className="text-sm font-medium">{order.clientName}</p>
              </Card>
            )}

            {order.companyName && (
              <Card className="p-4">
                <p className="text-xs text-muted-foreground mb-2">Empresa</p>
                <p className="text-sm font-medium">{order.companyName}</p>
              </Card>
            )}

            {/* Botón de cierre */}
            <Button onClick={onClose} className="w-full" variant="outline">
              Cerrar
            </Button>
          </div>
        ) : null}
      </DialogContent>
    </Dialog>
  );
}

'use client';

import React, { useCallback, useEffect, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import {
    DndContext,
    closestCenter,
    KeyboardSensor,
    PointerSensor,
    useSensor,
    useSensors,
    DragEndEvent,
} from '@dnd-kit/core';
import {
    arrayMove,
    SortableContext,
    sortableKeyboardCoordinates,
    verticalListSortingStrategy,
    horizontalListSortingStrategy,
} from '@dnd-kit/sortable';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { X, Image as ImageIcon, Video, Star, GripVertical, UploadCloud } from 'lucide-react';
import { MediaUploadItem } from '@/components/marketplace/types/marketplace.types';
import Image from 'next/image';

interface MediaUploaderProps {
    items: MediaUploadItem[];
    onChange: (items: MediaUploadItem[]) => void;
    error?: string;
}

const SortableMediaItem = ({
    item,
    onRemove,
    onSetMain,
}: {
    item: MediaUploadItem;
    onRemove: (id: string) => void;
    onSetMain: (id: string) => void;
}) => {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: item.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        zIndex: isDragging ? 10 : 1,
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            className={`relative flex flex-col md:flex-row items-center gap-3 p-3 bg-background border rounded-xl shadow-sm group ${
                isDragging ? 'shadow-md ring-2 ring-primary/50 opacity-90' : 'border-border'
            }`}
        >
            <div
                {...attributes}
                {...listeners}
                className="cursor-grab active:cursor-grabbing p-2 text-muted-foreground hover:text-foreground transition-colors touch-none"
            >
                <GripVertical className="w-5 h-5" />
            </div>

            <div className="relative w-full md:w-24 h-24 rounded-lg overflow-hidden bg-muted flex-shrink-0">
                {item.media_kind === 'image' ? (
                    <Image
                        src={item.previewUrl}
                        alt="Preview"
                        fill
                        className="object-cover"
                        unoptimized
                    />
                ) : (
                    <video
                        src={item.previewUrl}
                        className="w-full h-full object-cover"
                        muted
                        playsInline
                    />
                )}
                {item.media_role === 'main' && (
                    <div className="absolute top-1 left-1 bg-yellow-500 text-white p-1 rounded-full shadow-sm">
                        <Star className="w-3 h-3 fill-current" />
                    </div>
                )}
                <div className="absolute bottom-1 right-1 bg-black/60 text-white p-1 rounded-md backdrop-blur-sm">
                    {item.media_kind === 'image' ? (
                        <ImageIcon className="w-3 h-3" />
                    ) : (
                        <Video className="w-3 h-3" />
                    )}
                </div>
            </div>

            <div className="flex-1 min-w-0 flex flex-col justify-center">
                <p className="text-sm font-medium truncate text-foreground">
                    {item.file?.name || 'Archivo existente'}
                </p>
                <p className="text-xs text-muted-foreground">
                    {item.file ? `${(item.file.size / 1024 / 1024).toFixed(2)} MB` : 'Ya subido'}
                </p>
            </div>

            <div className="flex items-center gap-2 mt-2 md:mt-0">
                {item.media_role !== 'main' && (
                    <button
                        type="button"
                        onClick={() => onSetMain(item.id)}
                        className="text-xs font-medium px-3 py-1.5 rounded-lg border border-border hover:bg-muted transition-colors"
                    >
                        Hacer principal
                    </button>
                )}
                <button
                    type="button"
                    onClick={() => onRemove(item.id)}
                    className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                    title="Eliminar"
                >
                    <X className="w-5 h-5" />
                </button>
            </div>
        </div>
    );
};

export const MediaUploader: React.FC<MediaUploaderProps> = ({ items, onChange, error }) => {
    const sensors = useSensors(
        useSensor(PointerSensor),
        useSensor(KeyboardSensor, {
            coordinateGetter: sortableKeyboardCoordinates,
        })
    );

    // Cleanup object URLs to avoid memory leaks
    useEffect(() => {
        return () => {
            items.forEach((item) => {
                if (item.previewUrl.startsWith('blob:')) {
                    URL.revokeObjectURL(item.previewUrl);
                }
            });
        };
    }, []); // Note: not doing it on every items change to avoid revoking currently used ones until unmount, or we could track removed ones.

    const onDrop = useCallback(
        (acceptedFiles: File[]) => {
            const newItems: MediaUploadItem[] = acceptedFiles.map((file) => {
                const isVideo = file.type.startsWith('video/');
                return {
                    id: Math.random().toString(36).substring(2, 9),
                    file,
                    previewUrl: URL.createObjectURL(file),
                    media_kind: isVideo ? 'video' : 'image',
                    media_role: 'gallery',
                };
            });

            const nextItems = [...items, ...newItems];
            
            // Automatically set first item as main if none is set
            if (nextItems.length > 0 && !nextItems.some((i) => i.media_role === 'main')) {
                nextItems[0].media_role = 'main';
            }

            onChange(nextItems);
        },
        [items, onChange]
    );

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        accept: {
            'image/jpeg': [],
            'image/png': [],
            'image/webp': [],
            'image/avif': [],
            'video/mp4': [],
            'video/webm': [],
        },
        maxSize: 50 * 1024 * 1024, // 50MB
    });

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;

        if (over && active.id !== over.id) {
            const oldIndex = items.findIndex((item) => item.id === active.id);
            const newIndex = items.findIndex((item) => item.id === over.id);
            onChange(arrayMove(items, oldIndex, newIndex));
        }
    };

    const handleRemove = (id: string) => {
        const itemToRemove = items.find((i) => i.id === id);
        if (itemToRemove && itemToRemove.previewUrl.startsWith('blob:')) {
            URL.revokeObjectURL(itemToRemove.previewUrl);
        }

        const filtered = items.filter((item) => item.id !== id);
        
        // If we removed the main item, set the first available item as main
        if (itemToRemove?.media_role === 'main' && filtered.length > 0) {
            filtered[0].media_role = 'main';
        }

        onChange(filtered);
    };

    const handleSetMain = (id: string) => {
        const updated = items.map((item) => ({
            ...item,
            media_role: (item.id === id ? 'main' : 'gallery') as 'main' | 'gallery',
        }));
        // Sort main to top automatically? Optional, let's keep user's manual sorting
        onChange(updated);
    };

    return (
        <div className="space-y-4">
            <div
                {...getRootProps()}
                className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-colors ${
                    isDragActive
                        ? 'border-primary bg-primary/5'
                        : error
                        ? 'border-red-300 bg-red-50/50 hover:bg-red-50 dark:bg-red-900/40 dark:hover:bg-red-900/60'
                        : 'border-border hover:bg-muted/50'
                }`}
            >
                <input {...getInputProps()} />
                <div className="flex flex-col items-center gap-3">
                    <div className={`p-4 rounded-full ${isDragActive ? 'bg-primary/10' : 'bg-muted'}`}>
                        <UploadCloud className={`w-8 h-8 ${isDragActive ? 'text-primary' : 'text-muted-foreground'}`} />
                    </div>
                    <div>
                        <p className="text-sm font-medium text-foreground">
                            Arrastra archivos aquí, o haz clic para seleccionar
                        </p>
                        <p className="text-xs text-muted-foreground mt-1">
                            Soporta imágenes (JPG, PNG, WEBP) hasta 10MB y videos (MP4, WEBM) hasta 50MB
                        </p>
                    </div>
                </div>
            </div>

            {error && <p className="text-sm text-red-500 font-medium">{error}</p>}

            {items.length > 0 && (
                <div className="space-y-2">
                    <p className="text-sm font-semibold text-foreground flex items-center justify-between">
                        Archivos seleccionados ({items.length})
                        <span className="text-xs font-normal text-muted-foreground">
                            Arrastra para ordenar
                        </span>
                    </p>
                    <DndContext
                        sensors={sensors}
                        collisionDetection={closestCenter}
                        onDragEnd={handleDragEnd}
                    >
                        <SortableContext items={items.map(i => i.id)} strategy={verticalListSortingStrategy}>
                            <div className="space-y-2">
                                {items.map((item) => (
                                    <SortableMediaItem
                                        key={item.id}
                                        item={item}
                                        onRemove={handleRemove}
                                        onSetMain={handleSetMain}
                                    />
                                ))}
                            </div>
                        </SortableContext>
                    </DndContext>
                </div>
            )}
        </div>
    );
};

