"use client";

import React, { useRef } from 'react';
import { motion, useMotionValue, useMotionTemplate, useAnimationFrame } from "framer-motion";
import { cn } from "@/lib/utils/cn";

export const InfiniteGrid = ({ children, className }: { children?: React.ReactNode, className?: string }) => {
    const gridSize = 40;
    const containerRef = useRef<HTMLDivElement>(null);

    const mouseX = useMotionValue(0);
    const mouseY = useMotionValue(0);

    const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
        const { left, top } = e.currentTarget.getBoundingClientRect();
        mouseX.set(e.clientX - left);
        mouseY.set(e.clientY - top);
    };

    const gridOffsetX = useMotionValue(0);
    const gridOffsetY = useMotionValue(0);

    const speedX = 0.15;
    const speedY = 0.15;

    useAnimationFrame(() => {
        const currentX = gridOffsetX.get();
        const currentY = gridOffsetY.get();
        gridOffsetX.set((currentX + speedX) % gridSize);
        gridOffsetY.set((currentY + speedY) % gridSize);
    });

    const maskImage = useMotionTemplate`radial-gradient(300px circle at ${mouseX}px ${mouseY}px, black, transparent)`;

    return (
        <section
            ref={containerRef}
            onMouseMove={handleMouseMove}
            className={cn(
                "relative w-full overflow-hidden bg-background/50",
                className
            )}
        >
            {/* Layer 1: Subtle background grid (always visible) */}
            <div className="absolute inset-0 z-0 opacity-[0.07]">
                <GridPattern offsetX={gridOffsetX} offsetY={gridOffsetY} size={gridSize} />
            </div>

            {/* Layer 2: Highlighted grid (revealed by mouse mask) */}
            <motion.div
                className="absolute inset-0 z-0 opacity-85"
                style={{ maskImage, WebkitMaskImage: maskImage }}
            >
                <GridPattern offsetX={gridOffsetX} offsetY={gridOffsetY} size={gridSize} />
            </motion.div>

            {/* Decorative Blur Spheres */}
            <div className="absolute inset-0 pointer-events-none z-0">
                <div className="absolute right-[0%] top-[-10%] w-[40%] h-[40%] rounded-full bg-orange-500/10 dark:bg-orange-600/10 blur-[100px]" />
                <div className="absolute right-[20%] top-[10%] w-[20%] h-[20%] rounded-full bg-primary/10 blur-[80px]" />
                <div className="absolute left-[-5%] bottom-[-10%] w-[35%] h-[35%] rounded-full bg-blue-500/10 dark:bg-blue-600/10 blur-[100px]" />
            </div>

            {/* Content */}
            <div className="relative z-10 w-full h-full flex flex-col items-center justify-center">
                {children}
            </div>
        </section>
    );
};

const GridPattern = ({ offsetX, offsetY, size }: { offsetX: any; offsetY: any; size: number }) => {
    return (
        <svg className="w-full h-full absolute inset-0">
            <defs>
                <motion.pattern
                    id="grid-pattern"
                    width={size}
                    height={size}
                    patternUnits="userSpaceOnUse"
                    x={offsetX}
                    y={offsetY}
                >
                    <path
                        d={`M ${size} 0 L 0 0 0 ${size}`}
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1"
                        className="text-muted-foreground"
                    />
                </motion.pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#grid-pattern)" />
        </svg>
    );
};

"use client"

import { createContext, useContext, useState, useEffect } from "react"
import { logout as logoutService } from "@/services/auth.service" // ✅ NUEVO

type AuthContextType = {
  user: any
  setUser: (user: any) => void // ✅ NUEVO
  login: (email: string, password: string) => Promise<void>
  register: (name: string, email: string, password: string) => Promise<void>
  logout: () => void
}

const AuthContext = createContext<AuthContextType | null>(null)

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<any>(null)

  // ✅ NUEVO: persistencia de sesión
  useEffect(() => {
    const token = localStorage.getItem("token")
    const email = localStorage.getItem("email")
    const name = localStorage.getItem("name")

    if (token && email && name) {
      setUser({ email, name })
    }
  }, [])

  async function login(email: string, password: string) {
    console.log("login", email, password)
    setUser({ email })
  }

  async function register(name: string, email: string, password: string) {
    console.log("register", name, email, password)
    setUser({ name, email })
  }

  // 🔥 MODIFICADO: logout también en backend
  async function logout() {
    await logoutService()

    localStorage.removeItem("token")
    localStorage.removeItem("email")
    localStorage.removeItem("name")

    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, setUser, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)

  if (!context) {
    throw new Error("useAuth must be used inside AuthProvider")
  }

  return context
}

import { useState, useCallback, useMemo } from "react";
import { Product, ProductAttribute, AttributeValues, CreateOrderItemPayload } from "@/types/product";

export function useProductAttributes(product: Product & { attributes?: ProductAttribute[] }) {
  const [values, setValues] = useState<AttributeValues>({});

  const setValue = useCallback((code: string, value: string) => {
    setValues((prev) => ({ ...prev, [code]: value }));
  }, []);

  const attributes = product.attributes || [];

  // Calcula el precio final sumando los modificadores de las opciones seleccionadas
  const totalPrice = useMemo(() => {
    return product.price;
  }, [product, values, attributes]);

  // Validación: devuelve los campos requeridos sin valor
  const missingRequired = useMemo(() => {
    return attributes
      .filter((a) => a.required && !values[a.code])
      .map((a) => a.label);
  }, [attributes, values]);

  const isValid = missingRequired.length === 0;

  const getPayload = (): CreateOrderItemPayload => ({
    productId: product.id,
    quantity: 1,
    attributes: values,
  });

  return { values, setValue, totalPrice, isValid, missingRequired, getPayload };
}

