export const uploadProductMedia = async (
    companyId: number,
    productId: number,
    mediaItems: MediaUploadItem[],
    userId?: number
): Promise<FileAsset[] | null> => {
    try {
        const fileAssets: FileAsset[] = [];

        for (let i = 0; i < mediaItems.length; i++) {
            const item = mediaItems[i];
            
            // Skip already uploaded items
            if (!item.file) continue;

            // Upload via backend to safely bypass RLS and insert to database
            const dbData = await funcionarioMarketplaceService.uploadProductMedia(
                productId,
                companyId,
                item.media_kind,
                item.media_role,
                i,
                item.file
            );

            fileAssets.push(dbData);
        }

        return fileAssets;
    } catch (error) {
        console.error('uploadProductMedia failed:', error);
        throw error;
    }
};

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

function getAuthToken(): string {
  const token = localStorage.getItem("token");
  if (!token) {
    throw new Error("AUTH_REQUIRED");
  }
  return token;
}

function handleUnauthorized(): never {
  localStorage.removeItem("token");
  localStorage.removeItem("user_name");
  localStorage.removeItem("role");
  throw new Error("SESSION_EXPIRED");
}

async function parseError(res: Response): Promise<never> {
  if (res.status === 401) {
    handleUnauthorized();
  }

  let detail = "No se pudo completar la operación";
  try {
    const data = await res.json();
    
    // Handle Pydantic validation errors (array of error objects)
    if (Array.isArray(data?.detail)) {
      const errors = data.detail
        .map((err: any) => {
          const field = Array.isArray(err.loc) ? err.loc.join('.') : 'unknown';
          const msg = err.msg || 'Invalid field';
          return `${field}: ${msg}`;
        })
        .join('; ');
      detail = errors || detail;
    } else if (typeof data?.detail === 'string') {
      detail = data.detail;
    } else if (data?.message) {
      detail = data.message;
    }
  } catch {
    // ignore parse errors
  }

  throw new Error(detail);
}

