      await parseError(res);
    }

    return res.json();
  },

  async createMarketplaceOrder(payload: CreateMarketplaceOrderPayload): Promise<CreateOrderResponse> {
    const token = getAuthToken();

    const res = await fetch(`${API_URL}/orders/marketplace`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify(payload),
    });

    if (!res.ok) {
      await parseError(res);
    }

    return res.json();
  },

  async getPaymentStatus(orderId: number): Promise<PaymentStatusResponse> {
    const token = getAuthToken();

    const res = await fetch(`${API_URL}/orders/${orderId}/payment-status`, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!res.ok) {
      await parseError(res);
    }

    return res.json();
  },

  async generatePaymentUrl(orderId: number): Promise<CreateOrderResponse> {
    const token = getAuthToken();

    const res = await fetch(`${API_URL}/orders/${orderId}/payment-url`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!res.ok) {
      await parseError(res);
    }

    return res.json();
  },

  submitToPayU(actionUrl: string, payload: Record<string, string>) {
    const form = document.createElement("form");
    form.method = "POST";
    form.action = actionUrl;
    form.style.display = "none";

    Object.entries(payload).forEach(([key, value]) => {
      const input = document.createElement("input");
      input.type = "hidden";
      input.name = key;
      input.value = value;
      form.appendChild(input);
    });

    document.body.appendChild(form);
    form.submit();
  },
};

import { ProductAttribute } from "@/types/product";

const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

export const productAttributesService = {
  async getProductAttributes(productId: number | string): Promise<ProductAttribute[]> {
    const res = await fetch(`${API_URL}/products/${productId}/attributes`);
    
    if (!res.ok) {
      throw new Error("Failed to fetch product attributes");
    }

    const data = await res.json();
    
    return data.map((attr: any) => ({
      id: attr.id,
      code: attr.code,
      label: attr.label,
      input_type: attr.input_type,
      required: attr.required,
      placeholder: attr.placeholder,
      sort_order: attr.sort_order,
    }));
  }
};

import { Product } from "@/types/product";
import { normalizeProductType } from "@/constants/productCatalog";

type ProductApiResponse = {
  id: number;
  title: string;
  description: string;
  imageUrl: string | null;
  media?: any[];
  price: number;
  rating: number;
  reviews: number;
  inStock: boolean;
  stock: number;
  productType: string;
  productShape?: string | null;
  productShapeId?: number | null;
  attributes?: any[];
};

function toProduct(apiProduct: ProductApiResponse): Product {
  const normalizedType = normalizeProductType(apiProduct.productType) || "bordado";

  return {
    id: apiProduct.id,
    title: apiProduct.title,
    description: apiProduct.description,
    imageUrl: apiProduct.imageUrl || undefined,
    media: apiProduct.media || [],
    price: Number(apiProduct.price),
    rating: Number(apiProduct.rating || 0),
    reviews: Number(apiProduct.reviews || 0),
    inStock: Boolean(apiProduct.inStock),
    stock: Number(apiProduct.stock || 0),
    productType: normalizedType,
    productShape: apiProduct.productShape || null,
    productShapeId: apiProduct.productShapeId ?? null,
    attributes: apiProduct.attributes || [],
  };
}

export class ProductService {
  static async getProducts(): Promise<Product[]> {
    const res = await fetch(`${process.env.NEXT_PUBLIC_API_URL}/products/`);

    if (!res.ok) {
      throw new Error("Error fetching products");
    }

    const data: ProductApiResponse[] = await res.json();
    return data.map(toProduct);
  }

  static async getProductById(id: string): Promise<Product> {
    // Note: Since the backend currently lacks a specific /products/:id endpoint, 
    // we fetch the catalog and filter. In production with a large catalog, 
    // a specific backend endpoint should be added.
    const products = await ProductService.getProducts();
    const product = products.find(p => p.id.toString() === id);

    if (!product) {
      throw new Error("Product not found");
    }

    return product;
  }
}

